package com.celebritymode;

import com.celebritymode.appearance.FanGearTier;
import com.celebritymode.chat.*;
import com.celebritymode.fan.ArrivalPace;
import com.celebritymode.fan.CrowdArrival;
import com.celebritymode.movement.FormationStyle;
import com.celebritymode.pm.TrafficIntensity;

import net.runelite.client.config.*;

@ConfigGroup(CelebrityModeConfig.GROUP)
public interface CelebrityModeConfig extends Config {
    String GROUP = "celebritymode";

    @ConfigSection(name = "Crowd", description = "Size and formation", position = 0)
    String crowd = "crowd";

    @ConfigSection(
            name = "Appearance",
            description = "Persistent cosmetic appearances",
            position = 1)
    String appearance = "appearance";

    @ConfigSection(name = "Chatter", description = "Custom lines and activity-aware overhead dialogue", position = 2)
    String chatter = "chatter";

    @ConfigSection(name = "Behavior", description = "Reactions and diagnostics", position = 3)
    String behavior = "behavior";

    @ConfigSection(name = "Fan inbox", description = "Simulated incoming private messages", position = 4)
    String fanInbox = "fanInbox";

    @ConfigItem(
            keyName = "enableFanPms",
            name = "Enable fan PMs",
            description = "Simulate incoming fan messages in native private chat; independent of the overhead crowd",
            section = fanInbox,
            position = 0)
    default boolean enableFanPms() { return false; }

    @ConfigItem(
            keyName = "pmTrafficIntensity",
            name = "Traffic intensity",
            description = "Target averages: Relaxed 20, Streamer 80, Global Celebrity 180, Peak World Record 360 PMs/min",
            section = fanInbox,
            position = 1)
    default TrafficIntensity pmTrafficIntensity() { return TrafficIntensity.RELAXED; }

    @ConfigItem(
            keyName = "pmNotificationSound",
            name = "Play native notification sound",
            description = "Native UI sound, at most once every two seconds; respects sound-effect volume",
            section = fanInbox,
            position = 2)
    default boolean pmNotificationSound() { return false; }

    @Range(min = 1, max = CrowdArrival.MAX_FANS)
    @ConfigItem(
            keyName = "crowdSize",
            name = "Crowd size",
            description = "Maximum simulated fans; attendance varies slightly over time",
            section = crowd,
            position = 0)
    default int crowdSize() {
        return 8;
    }

    @ConfigItem(
            keyName = "showCrowd",
            name = "Show crowd",
            description = "Hide or show your fan club while keeping your settings",
            section = crowd,
            position = 4)
    default boolean showCrowd() {
        return true;
    }

    @ConfigItem(
            keyName = "arrivalPace",
            name = "Arrival pace",
            description = "Build your fan club gradually, quickly, or all at once; applies to new arrivals",
            section = crowd,
            position = 5)
    default ArrivalPace arrivalPace() {
        return ArrivalPace.GRADUAL;
    }

    @ConfigItem(
            keyName = "formationStyle",
            name = "Formation",
            description = "How your entourage follows",
            section = crowd,
            position = 1)
    default FormationStyle formationStyle() {
        return FormationStyle.ENTOURAGE;
    }

    @ConfigItem(
            keyName = "respectPersonalSpace",
            name = "Personal space",
            description = "Prefer distinct tiles; avoid your tile while gathering close",
            section = crowd,
            position = 2)
    default boolean respectPersonalSpace() {
        return true;
    }

    @Range(min = 1, max = 8)
    @ConfigItem(
            keyName = "maxSpread",
            name = "Maximum spread",
            description = "Lateral spread in tiles",
            section = crowd,
            position = 3)
    default int maxSpread() {
        return 2;
    }

    @ConfigItem(
            keyName = "crowdGearTier",
            name = "Gear theme",
            description = "Randomized player outfits",
            section = appearance,
            position = 0)
    default FanGearTier crowdGearTier() {
        return FanGearTier.MIXED;
    }

    @ConfigItem(
            keyName = "showFanNames",
            name = "Show fan names",
            description = "Draw simulated usernames above fans",
            section = appearance,
            position = 1)
    default boolean showFanNames() {
        return false;
    }

    @ConfigItem(
            keyName = "chatFrequency",
            name = "Chat frequency",
            description = "Normal is busy; Spam keeps the crowd constantly shouting",
            section = chatter,
            position = 0)
    default ChatFrequency chatFrequency() {
        return ChatFrequency.SPAM;
    }

    @ConfigItem(
            keyName = "customQuotes",
            name = "Custom quotes",
            description = "Your own dialogue, one quote per line (or comma separated). Supports {player}, {gear}, {target}, {skill}, {level}",
            section = chatter,
            position = 1)
    default String customQuotes() {
        return "";
    }

    @ConfigItem(
            keyName = "customQuoteMode",
            name = "Quote source",
            description = "Built-in activity-aware chatter, your custom lines, or both; empty custom-only is silent",
            section = chatter,
            position = 2)
    default CustomQuoteMode customQuoteMode() {
        return CustomQuoteMode.MIXED;
    }

    @ConfigItem(
            keyName = "reactToEvents",
            name = "React to events",
            description = "Occasional idle emotes plus recognition, level and death reactions; activity chatter uses Quote source",
            section = behavior,
            position = 0)
    default boolean reactToEvents() {
        return true;
    }

    @ConfigItem(
            keyName = "debugMode",
            name = "Debug overlay",
            description = "Show trail, target tiles and follower state",
            section = behavior,
            position = 1)
    default boolean debugMode() {
        return false;
    }
}

package com.celebritymode;

import com.celebritymode.fan.FanManager;
import com.celebritymode.pm.FanPmEngine;
import com.celebritymode.overlay.CelebrityModeOverlay;
import com.celebritymode.ui.CelebrityModeIcon;
import com.celebritymode.ui.CelebrityModePanel;
import com.google.inject.Provides;

import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import java.util.*;

import javax.inject.*;
import javax.swing.SwingUtilities;

@PluginDescriptor(
        name = "Fame Simulator",
        description = "Feel famous in OSRS with your own simulated fan club, reactive crowd chatter, and optional fan PMs",
        tags = {
            "fun", "cosmetic", "crowd", "followers", "fans", "npc", "fame", "famous",
            "celebrity", "simulator", "simulation", "chat", "dialogue", "pm", "private messages",
            "roleplay", "social", "streamer", "streaming", "screenshot", "video", "creator"
        })
public class CelebrityModePlugin extends Plugin {
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private OverlayManager overlayManager;
    @Inject private FanManager fanManager;
    @Inject private FanPmEngine fanPmEngine;
    @Inject private CelebrityModeOverlay overlay;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ConfigManager configManager;
    @Inject private CelebrityModeConfig config;
    // Created, refreshed, and removed only on the Swing event thread.
    private CelebrityModePanel panel;
    private NavigationButton navigation;
    private final EnumMap<Skill, Integer> levels = new EnumMap<>(Skill.class);
    private volatile boolean enabled;

    @Provides
    CelebrityModeConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(CelebrityModeConfig.class);
    }

    @Provides
    @Singleton
    Random provideRandom() {
        return new Random();
    }

    @Override
    protected void startUp() {
        enabled = true;
        fanPmEngine.startUp();
        overlayManager.add(overlay);
        SwingUtilities.invokeLater(() -> {
            if (!enabled || navigation != null) return;
            panel = new CelebrityModePanel(config,
                    (key, value) -> configManager.setConfiguration(CelebrityModeConfig.GROUP, key, value));
            navigation = NavigationButton.builder()
                    .tooltip("Fame Simulator")
                    .icon(CelebrityModeIcon.create(32))
                    .priority(7)
                    .panel(panel)
                    .build();
            clientToolbar.addNavigation(navigation);
        });
        clientThread.invoke(
                () -> {
                    if (enabled) {
                        fanManager.cleanup();
                        levels.clear();
                    }
                });
    }

    @Override
    protected void shutDown() {
        enabled = false;
        fanPmEngine.shutDown();
        overlayManager.remove(overlay);
        SwingUtilities.invokeLater(() -> {
            if (navigation != null) clientToolbar.removeNavigation(navigation);
            navigation = null;
            panel = null;
        });
        clientThread.invoke(
                () -> {
                    if (!enabled) {
                        fanManager.cleanup();
                        levels.clear();
                    }
                });
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (enabled) fanManager.onGameTick(client.getLocalPlayer());
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (enabled) {
            fanManager.onClientTick();
            fanPmEngine.onClientTick();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        fanManager.onGameStateChanged(event.getGameState());
        fanPmEngine.onGameStateChanged(event.getGameState());
        if (event.getGameState() != GameState.LOGGED_IN
                && event.getGameState() != GameState.LOADING) levels.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (enabled && CelebrityModeConfig.GROUP.equals(event.getGroup())) {
            SwingUtilities.invokeLater(() -> {
                if (enabled && panel != null) panel.refresh(event.getKey());
            });
            clientThread.invoke(
                    () -> {
                        if (enabled) {
                            fanManager.onConfigChanged(event.getKey());
                            if (event.getKey().startsWith("pm") || "enableFanPms".equals(event.getKey()))
                                fanPmEngine.onClientTick();
                        }
                    });
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        Integer old = levels.put(event.getSkill(), event.getLevel());
        if (enabled && client.getGameState() == GameState.LOGGED_IN) {
            fanManager.onExperience(event.getSkill(), event.getXp());
            if (old != null && event.getLevel() > old)
                fanManager.reactLevel(event.getSkill(), event.getLevel());
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (enabled && client.getGameState() == GameState.LOGGED_IN)
            fanManager.onMenuOption(event.getMenuOption());
    }

    @Subscribe
    public void onActorDeath(ActorDeath event) {
        if (enabled && event.getActor() == client.getLocalPlayer()) fanManager.react(true);
    }
}

package com.celebritymode.appearance;

import java.util.*;

import javax.inject.*;

/** Discovers current wearable cache items incrementally; no preset wardrobe or external data. */
@Singleton
public final class EquipmentCatalog {
    public static final class Item {
        public final int id, slot;
        public final String name, family;
        public final boolean members, twoHanded;

        Item(int id, FanModelFactory.Definition d) {
            this.id = id;
            slot = d.slot;
            name = d.name;
            members = d.members;
            twoHanded = d.wear2 == 5 || d.wear3 == 5;
            family = family(name);
        }
    }

    private final FanModelFactory models;
    private final Map<Integer, List<Item>> bySlot = new HashMap<>();
    private int[] ids;
    private int cursor, stride;

    @Inject
    public EquipmentCatalog(FanModelFactory models) {
        this.models = models;
    }

    public void advance(int budget) {
        if (ids == null) {
            ids = models.itemIds();
            stride = 7919;
            if (ids == null) return;
            while (ids.length > 0 && gcd(stride, ids.length) != 1) stride++;
        }
        for (int count = 0; cursor < ids.length && count < budget; count++, cursor++) {
            int id = ids[(int) ((long) cursor * stride % ids.length)];
            try {
                FanModelFactory.Definition d = models.readEquipment(id);
                if (d == null) {
                    ids = null;
                    return;
                } // Cache readiness retry without keeping an incomplete index.
                if (d.slot < 0
                        || d.models[0] < 0
                        || d.name.isEmpty()
                        || d.noteTemplate >= 0
                        || d.placeholderTemplate >= 0
                        || Arrays.stream(d.actions)
                                .noneMatch(
                                        action ->
                                                "Wear".equalsIgnoreCase(action)
                                                        || "Wield".equalsIgnoreCase(action)
                                                        || "Equip".equalsIgnoreCase(action)))
                    continue;
                String name = d.name.toLowerCase(Locale.ENGLISH);
                if (name.contains("broken")
                        || name.contains("inactive")
                        || name.contains("(l)")
                        || name.contains("(or)")
                        || name.contains("(uncharged)")
                        || name.startsWith("null")) continue;
                List<Item> pool = bySlot.computeIfAbsent(d.slot, k -> new ArrayList<>());
                pool.add(new Item(id, d));
            } catch (IllegalArgumentException ex) {
                /* Unknown future definition formats are excluded. */
            }
        }
    }

    public Item choose(int slot, FanGearTier tier, String affinity, Random random) {
        List<Item> pool = bySlot.getOrDefault(slot, Collections.emptyList());
        Item picked = null;
        int candidates = 0;
        boolean familyAvailable = false;
        if (affinity != null)
            for (Item item : pool)
                if (matches(item, tier) && item.family.equals(affinity)) {
                    familyAvailable = true;
                    break;
                }
        for (Item item : pool)
            if (matches(item, tier) && (!familyAvailable || item.family.equals(affinity)))
                if (random.nextInt(++candidates) == 0) picked = item;
        return picked;
    }

    static boolean matches(Item item, FanGearTier tier) {
        String name = item.name.toLowerCase(Locale.ENGLISH);
        switch (tier) {
            case DEFAULT_BOB:
                return false;
            case BRONZE_NOOB:
                return name.startsWith("bronze ")
                        || (item.slot == 1 && name.contains("cape"))
                        || (item.slot == 9 || item.slot == 10) && name.startsWith("leather ");
            case F2P_WARRIOR:
                return !item.members;
            case MODERN_GEAR:
                return item.id >= 20000;
            case MIDGAME_WARRIOR:
                return item.members;
            default:
                return true;
        }
    }

    static String family(String name) {
        String clean = name.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9 ]", "").trim();
        String[] words = clean.split(" +");
        return words.length > 1 && words[1].equals("moon") ? words[0] + " moon" : words[0];
    }

    public int size() {
        int size = 0;
        for (List<Item> items : bySlot.values()) size += items.size();
        return size;
    }

    public boolean complete() {
        return ids != null && cursor >= ids.length;
    }

    public void clear() {
        ids = null;
        cursor = 0;
        bySlot.clear();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int next = a % b;
            a = b;
            b = next;
        }
        return a;
    }
}

package com.celebritymode.appearance;

/** Immutable spawn-time definition; no Player or PlayerComposition is ever mutated. */
public final class FanAppearance {
    public final int[] kits, equipment;
    public final short[] colors;
    public final FanGearTier tier;
    public final String weaponName;

    public FanAppearance(int[] kits, int[] equipment, short[] colors, FanGearTier tier) {
        this(kits, equipment, colors, tier, "");
    }

    public FanAppearance(
            int[] kits, int[] equipment, short[] colors, FanGearTier tier, String weaponName) {
        this.kits = kits.clone();
        this.equipment = equipment.clone();
        this.colors = colors.clone();
        this.tier = tier;
        this.weaponName = weaponName.toLowerCase(java.util.Locale.ENGLISH);
    }
}

package com.celebritymode.appearance;

import java.util.*;
import java.util.Random;

import javax.inject.*;

@Singleton
public final class FanAppearanceFactory {
    private final Random random;
    private final FanModelFactory models;
    private final EquipmentCatalog catalog;
    // Male body palettes in the cache's packed HSL color space, applied before equipment.
    private static final short[][] COLORS = {
        {6798, 8741, 25238, 4626, 4550, 5681},
        {8741, 12, 4626, 4550, 5681, 25238},
        {25238, 8741, 12, 4626, 4550, 5681},
        {4626, 12, 4550, 5681, 8741},
        {4550, 4510, 4537, 5673, 5681}
    };

    @Inject
    public FanAppearanceFactory(Random random, FanModelFactory models) {
        this.random = random;
        this.models = models;
        catalog = new EquipmentCatalog(models);
    }

    public FanAppearance createAppearance(int index, FanGearTier requested) {
        FanGearTier tier = requested == FanGearTier.MIXED ? mixedTier() : requested;
        int[] kits = new int[7];
        for (int part = 0; part < 7; part++)
            kits[part] = models.chooseKit(part, random, tier == FanGearTier.DEFAULT_BOB);
        short[] colors = new short[5];
        for (int i = 0; i < colors.length; i++)
            colors[i] = COLORS[i][random.nextInt(COLORS[i].length)];
        // Bounded scanning samples across the whole cache, so modern items appear immediately.
        catalog.advance(256);
        List<EquipmentCatalog.Item> chosen = new ArrayList<>();
        EquipmentCatalog.Item body = catalog.choose(4, tier, null, random);
        if (body != null) chosen.add(body);
        String affinity = body == null ? null : body.family;
        for (int slot : new int[] {0, 7, 10, 9, 1, 2, 3}) {
            if ((slot == 2 || slot == 0) && random.nextInt(5) == 0) continue;
            EquipmentCatalog.Item item =
                    catalog.choose(
                            slot,
                            tier,
                            tier == FanGearTier.RANDOM_FASHIONSCAPE
                                            || slot == 3
                                            || slot == 1
                                            || slot == 2
                                    ? null
                                    : affinity,
                            random);
            if (item != null) chosen.add(item);
        }
        EquipmentCatalog.Item weapon = null;
        for (EquipmentCatalog.Item item : chosen) if (item.slot == 3) weapon = item;
        if (weapon == null || !weapon.twoHanded) {
            EquipmentCatalog.Item shield = catalog.choose(5, tier, null, random);
            if (shield != null) chosen.add(shield);
        }
        int[] equipment = chosen.stream().mapToInt(item -> item.id).toArray();
        String weaponName = weapon == null ? "" : weapon.name;
        return new FanAppearance(kits, equipment, colors, tier, weaponName);
    }

    private FanGearTier mixedTier() {
        int roll = random.nextInt(100);
        return roll < 5
                ? FanGearTier.DEFAULT_BOB
                : roll < 10
                        ? FanGearTier.BRONZE_NOOB
                        : roll < 20
                                ? FanGearTier.F2P_WARRIOR
                                : roll < 40
                                        ? FanGearTier.MIDGAME_WARRIOR
                                        : roll < 65
                                                ? FanGearTier.RANDOM_FASHIONSCAPE
                                                : FanGearTier.MODERN_GEAR;
    }

    public void advanceCatalog() {
        catalog.advance(256);
    }

    public EquipmentCatalog getCatalog() {
        return catalog;
    }

    public void clear() {
        catalog.clear();
    }
}

package com.celebritymode.appearance;

public enum FanGearTier {
    DEFAULT_BOB,
    BRONZE_NOOB,
    F2P_WARRIOR,
    MIDGAME_WARRIOR,
    RANDOM_FASHIONSCAPE,
    MODERN_GEAR,
    MIXED
}

package com.celebritymode.appearance;

import net.runelite.api.*;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.ByteBuffer;
import java.util.*;

import javax.inject.*;

/**
 * Public cache access only. Decodes IDK (archive 3) and OBJ (archive 10) worn meshes. Unknown
 * opcodes fail closed, rather than rendering inventory meshes as people. Cache definitions follow
 * RuneLite's KitLoader / ItemLoader format.
 */
@Singleton
public final class FanModelFactory {
    private static final Logger log = LoggerFactory.getLogger(FanModelFactory.class);
    private static final short[] BODY_COLORS = {6798, 8741, 25238, 4626, 4550};
    private final Client client;
    private final Map<Integer, Definition> kits = new LinkedHashMap<>(), items = new HashMap<>();

    @Inject
    public FanModelFactory(Client client) {
        this.client = client;
    }

    public int chooseKit(int part, Random random, boolean defaultBob) {
        if (kits.isEmpty()) {
            int[] ids = client.getIndexConfig().getFileIds(3);
            if (ids != null)
                for (int id : ids) {
                    byte[] data = client.getIndexConfig().loadData(3, id);
                    if (data == null) continue;
                    try {
                        Definition d = decode(data, true);
                        if (!d.hidden && d.part >= 0 && d.part < 7) kits.put(id, d);
                    } catch (IllegalArgumentException ex) {
                        log.debug("Skipping unsupported identity kit {}", id);
                    }
                }
        }
        List<Integer> candidates = new ArrayList<>();
        for (Map.Entry<Integer, Definition> e : kits.entrySet())
            if (e.getValue().part == part) candidates.add(e.getKey());
        if (candidates.isEmpty()) {
            kits.clear();
            throw new IllegalStateException("Body kits not available yet: " + part);
        }
        return candidates.get(defaultBob ? 0 : random.nextInt(candidates.size()));
    }

    public Model createModel(FanAppearance appearance) {
        try {
            return assemble(appearance, true);
        } catch (RuntimeException ex) {
            if (ex instanceof CacheUnavailable) throw ex;
            log.debug(
                    "Could not assemble {} outfit, falling back to body kits", appearance.tier, ex);
            return assemble(appearance, false);
        }
    }

    private Model assemble(FanAppearance appearance, boolean equipped) {
        List<ModelData> equipment = new ArrayList<>();
        boolean[] hidden = new boolean[7];
        if (equipped)
            for (int id : appearance.equipment) {
                Definition item = items.get(id);
                if (item == null) {
                    byte[] data = client.getIndexConfig().loadData(10, id);
                    if (data == null) throw new CacheUnavailable("Item unavailable: " + id);
                    item = decode(data, false);
                    items.put(id, item);
                }
                equipment.add(mesh(item));
                // Cache wear-position tags identify covered body kits, including arms/beards.
                int[] partSlots = {11, 8, 4, 6, 9, 7, 10};
                for (int part = 0; part < partSlots.length; part++)
                    if (item.slot == partSlots[part]
                            || item.wear2 == partSlots[part]
                            || item.wear3 == partSlots[part]) hidden[part] = true;
                // A head item replaces the hair/head kit; beard coverage follows cache tags.
                if (item.slot == 0) {
                    hidden[0] = true;
                }
                if (item.slot == 4) {
                    hidden[2] = true;
                    if (item.wear2 == 6) hidden[3] = true;
                }
                if (item.slot == 7) hidden[5] = true;
                if (item.slot == 9) hidden[4] = true;
                if (item.slot == 10) hidden[6] = true;
            }
        List<ModelData> body = new ArrayList<>();
        for (int part = 0; part < 7; part++)
            if (!hidden[part]) {
                Definition kit = kits.get(appearance.kits[part]);
                if (kit == null) throw new IllegalStateException("Missing body kit");
                body.add(mesh(kit));
            }
        if (!body.isEmpty()) {
            ModelData skin = client.mergeModels(body.toArray(new ModelData[0])).cloneColors();
            recolorBody(skin.getFaceColors(), appearance.colors);
            equipment.add(skin);
        }
        return client.mergeModels(equipment.toArray(new ModelData[0]))
                .light(64, 850, -30, -50, -30);
    }

    private ModelData mesh(Definition def) {
        List<ModelData> parts = new ArrayList<>();
        for (int id : def.models)
            if (id >= 0) {
                ModelData data = client.loadModelData(id);
                if (data == null) throw new CacheUnavailable("Missing mesh " + id);
                parts.add(data);
            }
        if (parts.isEmpty()) throw new IllegalStateException("No worn model");
        ModelData data = client.mergeModels(parts.toArray(new ModelData[0])).cloneColors();
        for (short[] pair : def.recolors) data.recolor(pair[0], pair[1]);
        // Untextured meshes have a null face-texture array. RuneLite's cloneTextures()
        // clones that array directly, so only call it when textures actually exist.
        if (!def.retextures.isEmpty() && data.getFaceTextures() != null) {
            data.cloneTextures();
            for (short[] pair : def.retextures) data.retexture(pair[0], pair[1]);
        }
        if (def.offset != 0) {
            data.cloneVertices().translate(0, def.offset, 0);
        }
        return data;
    }

    static void recolorBody(short[] faces, short[] colors) {
        for (int face = 0; face < faces.length; face++)
            for (int part = 0; part < BODY_COLORS.length; part++)
                if (faces[face] == BODY_COLORS[part]) {
                    faces[face] = colors[part];
                    break;
                }
    }

    private static final class CacheUnavailable extends IllegalStateException {
        private static final long serialVersionUID = 1L;

        CacheUnavailable(String message) {
            super(message);
        }
    }

    Definition readEquipment(int id) {
        byte[] data = client.getIndexConfig().loadData(10, id);
        return data == null ? null : decode(data, false);
    }

    int[] itemIds() {
        return client.getIndexConfig().getFileIds(10);
    }

    public void clear() {
        kits.clear();
        items.clear();
    }

    static final class Definition {
        int part = -1, slot = -1, wear2 = -1, wear3 = -1, offset;
        boolean hidden, members, tradeable;
        int noteTemplate = -1, placeholderTemplate = -1;
        String name = "";
        String[] actions = new String[5];
        int[] models = new int[] {-1, -1, -1};
        final List<short[]> recolors = new ArrayList<>(), retextures = new ArrayList<>();
    }

    static Definition decode(byte[] bytes, boolean kit) {
        try {
            ByteBuffer b = ByteBuffer.wrap(bytes);
            Definition d = new Definition();
            while (b.hasRemaining()) {
                int op = u8(b);
                if (op == 0) return d;
                if (kit) {
                    if (op == 1) d.part = u8(b);
                    else if (op == 2 || op == 5) {
                        d.models = new int[u8(b)];
                        for (int i = 0; i < d.models.length; i++)
                            d.models[i] = op == 2 ? u16(b) : b.getInt();
                    } else if (op == 3) d.hidden = true;
                    else if (op == 40 || op == 41) pairs(b, op == 40 ? d.recolors : d.retextures);
                    else if (op >= 60 && op < 70) u16(b);
                    else if (op >= 70 && op < 80) b.getInt();
                    else throw new IllegalArgumentException("Unknown kit opcode " + op);
                    continue;
                }
                if (op == 23 || op == 45) {
                    d.models[0] = op == 23 ? u16(b) : b.getInt();
                    d.offset = u8(b);
                } else if (op == 24 || op == 46) d.models[1] = op == 24 ? u16(b) : b.getInt();
                else if (op == 78 || op == 47) d.models[2] = op == 78 ? u16(b) : b.getInt();
                else if (op == 13) d.slot = u8(b);
                else if (op == 14) d.wear2 = u8(b);
                else if (op == 27) d.wear3 = u8(b);
                else if (op == 16) d.members = true;
                else if (op == 65) d.tradeable = true;
                else if (op == 98) d.noteTemplate = u16(b);
                else if (op == 149) d.placeholderTemplate = u16(b);
                else if (op == 2) d.name = string(b);
                else if (op >= 35 && op < 40) d.actions[op - 35] = string(b);
                else if (op == 40 || op == 41) pairs(b, op == 40 ? d.recolors : d.retextures);
                else if (op == 2 || op == 3 || op == 9 || (op >= 30 && op < 40)) string(b);
                else if (op == 43) {
                    u8(b);
                    while (u8(b) != 0) string(b);
                } else if (op == 12 || op == 44 || (op >= 49 && op <= 54)) b.getInt();
                else if (op == 25) {
                    u16(b);
                    u8(b);
                } else if (op == 48) {
                    b.getInt();
                    u8(b);
                } else if (op == 1
                        || (op >= 4 && op <= 8)
                        || op == 26
                        || op == 75
                        || op == 79
                        || (op >= 90 && op <= 99)
                        || (op >= 110 && op <= 112)
                        || op == 139
                        || op == 140
                        || op == 148
                        || op == 149) u16(b);
                else if (op == 27 || op == 42 || op == 113 || op == 114 || op == 115) u8(b);
                else if (op >= 100 && op < 110) b.getInt();
                else if (op == 161) {
                    int count = u16(b);
                    for (int i = 0; i < count; i++) u16(b);
                } else if (op == 249) {
                    int count = u8(b);
                    for (int i = 0; i < count; i++) {
                        int type = u8(b);
                        u8(b);
                        u8(b);
                        u8(b);
                        if (type == 1) string(b);
                        else b.getInt();
                    }
                } else if (op != 11 && op != 15 && op != 16 && op != 65 && op != 160 && op != 251)
                    throw new IllegalArgumentException("Unknown item opcode " + op);
            }
            throw new IllegalArgumentException("Unterminated definition");
        } catch (java.nio.BufferUnderflowException ex) {
            throw new IllegalArgumentException("Truncated cache definition", ex);
        }
    }

    private static int u8(ByteBuffer b) {
        return b.get() & 255;
    }

    private static int u16(ByteBuffer b) {
        return b.getShort() & 65535;
    }

    private static String string(ByteBuffer b) {
        int start = b.position();
        while (b.get() != 0) {}
        return new String(
                b.array(),
                start,
                b.position() - start - 1,
                java.nio.charset.Charset.forName("windows-1252"));
    }

    private static void pairs(ByteBuffer b, List<short[]> pairs) {
        int count = u8(b);
        for (int i = 0; i < count; i++) pairs.add(new short[] {b.getShort(), b.getShort()});
    }
}

package com.celebritymode.chat;

import java.util.Random;

public enum ChatFrequency {
    OFF(0, 0),
    LOW(5, 10),
    NORMAL(1, 2),
    SPAM(1, 1);
    public final int minimumTicks, maximumTicks;

    ChatFrequency(int min, int max) {
        minimumTicks = min;
        maximumTicks = max;
    }

    public int delay(Random random) {
        return minimumTicks + random.nextInt(maximumTicks - minimumTicks + 1);
    }
}

package com.celebritymode.chat;

public enum CustomQuoteMode {
    BUILT_IN_ONLY,
    CUSTOM_ONLY,
    MIXED
}

package com.celebritymode.chat;

import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import java.util.*;

/** Client-thread-only observations. Login snapshots establish baselines, not fake XP gains. */
// RuneLite retains the deprecated OVERALL pseudo-skill in values(); exclude it from XP snapshots.
@SuppressWarnings("deprecation")
public final class FanActivityTracker {
    private final EnumMap<Skill, Integer> experience = new EnumMap<>(Skill.class);
    private Skill recentSkill;
    private int xpTick = Integer.MIN_VALUE,
            attackTick = Integer.MIN_VALUE,
            gearTick = Integer.MIN_VALUE;
    private int gain;
    private String previousGear;

    public void experience(Skill skill, int xp, int tick) {
        if (skill == Skill.OVERALL) return;
        Integer previous = experience.put(skill, xp);
        if (previous == null || xp <= previous || skill == Skill.HITPOINTS) return;
        recentSkill = skill;
        gain = xp - previous;
        xpTick = tick;
    }

    public void menu(String option, int tick) {
        if ("Attack".equalsIgnoreCase(FanChatContext.clean(option))) attackTick = tick;
    }

    public FanChatContext observe(
            Client client, Player player, String gear, boolean moved, boolean running, int tick) {
        for (Skill skill : Skill.values())
            if (skill != Skill.OVERALL)
                experience.putIfAbsent(skill, client.getSkillExperience(skill));
        String cleanGear = FanChatContext.clean(gear);
        if (previousGear != null && !previousGear.equals(cleanGear)) gearTick = tick;
        previousGear = cleanGear;
        boolean recentXp = (long) tick - xpTick <= 10;
        Skill skill = recentXp ? recentSkill : null;
        Actor target = player.getInteracting();
        boolean fighting =
                target != null
                        && ((long) tick - attackTick <= 8
                                || recentXp && combat(skill)
                                || target.getCombatLevel() > 0
                                        && target.getHealthRatio() >= 0
                                        && player.getAnimation() >= 0);
        Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        FanChatContext.Activity activity =
                bank != null && !bank.isHidden()
                        ? FanChatContext.Activity.BANKING
                        : fighting
                                ? FanChatContext.Activity.COMBAT
                                : recentXp
                                                && (!moved || skill == Skill.AGILITY)
                                                && (!combat(skill) || target == null)
                                        ? FanChatContext.Activity.SKILLING
                                        : moved
                                                ? running
                                                        ? FanChatContext.Activity.RUNNING
                                                        : FanChatContext.Activity.WALKING
                                                : FanChatContext.Activity.IDLE;
        int realHp = client.getRealSkillLevel(Skill.HITPOINTS);
        boolean lowHealth =
                fighting
                        && realHp > 0
                        && client.getBoostedSkillLevel(Skill.HITPOINTS) * 100 / realHp <= 30;
        return new FanChatContext(
                player.getName(),
                cleanGear,
                fighting ? target.getName() : "",
                activity,
                skill,
                skill == null ? 0 : client.getRealSkillLevel(skill),
                recentXp ? gain : 0,
                lowHealth,
                (long) tick - gearTick <= 8 && !cleanGear.isEmpty());
    }

    private static boolean combat(Skill skill) {
        return skill == Skill.ATTACK
                || skill == Skill.STRENGTH
                || skill == Skill.DEFENCE
                || skill == Skill.RANGED
                || skill == Skill.MAGIC
                || skill == Skill.HITPOINTS;
    }

    public void clear() {
        experience.clear();
        recentSkill = null;
        gain = 0;
        previousGear = null;
        xpTick = attackTick = gearTick = Integer.MIN_VALUE;
    }
}

package com.celebritymode.chat;

import net.runelite.api.Skill;

/** Observations about the local character, never guesses about loot or achievements. */
public final class FanChatContext {
    public enum Activity {
        IDLE,
        WALKING,
        RUNNING,
        BANKING,
        COMBAT,
        SKILLING
    }

    public final String player, gear, target;
    public final Activity activity;
    public final Skill skill;
    public final int level, gainedXp;
    public final boolean lowHealth, gearChanged;

    public FanChatContext(
            String player,
            String gear,
            String target,
            Activity activity,
            Skill skill,
            int level,
            int gainedXp,
            boolean lowHealth,
            boolean gearChanged) {
        this.player = clean(player);
        this.gear = clean(gear);
        this.target = clean(target);
        this.activity = activity;
        this.skill = skill;
        this.level = level;
        this.gainedXp = gainedXp;
        this.lowHealth = lowHealth;
        this.gearChanged = gearChanged;
    }

    public static FanChatContext idle(String name, String gear) {
        return new FanChatContext(name, gear, "", Activity.IDLE, null, 0, 0, false, false);
    }

    public static String clean(String value) {
        return value == null ? "" : value.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
    }
}

package com.celebritymode.chat;

import com.celebritymode.fan.*;
import com.celebritymode.generation.FanUtterance;

import java.util.*;
import java.util.regex.Pattern;

/** One crowd scheduler, rather than thirty competing timers. */
public final class FanChatManager {
    private static final Pattern PUNCTUATION = Pattern.compile("[^a-z0-9 ]");
    private static final Pattern SPACES = Pattern.compile(" +");
    private final Random random;
    private ChatFrequency frequency = ChatFrequency.OFF;
    private FanChatContext context = FanChatContext.idle("", "");
    private final Deque<String> recentCrowd = new ArrayDeque<>();
    private final Map<FanEntity, Deque<String>> recentFans = new IdentityHashMap<>();
    private final Deque<String> recentStructures = new ArrayDeque<>();
    private final Map<FanEntity, Deque<String>> fanStructures = new IdentityHashMap<>();
    private final Map<FanEntity, String> visibleStructures = new IdentityHashMap<>();
    private int nextTick = Integer.MAX_VALUE;
    private String lastQuote;
    private CustomQuoteMode mode = CustomQuoteMode.BUILT_IN_ONLY;
    private List<String> custom = Collections.emptyList();

    public FanChatManager(Random random) {
        this.random = random;
    }

    public void configure(ChatFrequency frequency, CustomQuoteMode mode, String custom, int tick) {
        this.frequency = frequency;
        this.mode = mode;
        List<String> parsed = FanQuoteLibrary.parse(custom);
        this.custom = parsed;

        nextTick =
                frequency == ChatFrequency.OFF ? Integer.MAX_VALUE : tick + frequency.delay(random);
    }

    public int getNextTick() {
        return nextTick;
    }

    public void tick(List<FanEntity> fans, int tick) {
        recentFans.keySet().retainAll(fans);
        fanStructures.keySet().retainAll(fans);
        visibleStructures.keySet().retainAll(fans);
        for (FanEntity fan : fans) if (tick >= fan.overheadExpiryTick) fan.overheadText = null;
        if (frequency == ChatFrequency.OFF || tick < nextTick) return;
        nextTick = tick + frequency.delay(random);
        List<FanEntity> eligible = new ArrayList<>(fans.size());
        int visible = 0;
        for (FanEntity fan : fans) {
            if (!fan.isVisible()) continue;
            visible++;
            if (tick >= fan.nextChatTick
                    && (mode != CustomQuoteMode.CUSTOM_ONLY || !custom.isEmpty()))
                eligible.add(fan);
        }
        Collections.shuffle(eligible, random);
        int batch =
                frequency == ChatFrequency.LOW
                        ? 1
                        : frequency == ChatFrequency.NORMAL
                                ? Math.max(1, (visible + 2) / 3)
                                : Math.max(1, (2 * visible + 2) / 3);
        for (int i = 0; i < Math.min(batch, eligible.size()); i++) {
            FanEntity fan = eligible.get(i);
            say(fan, chooseFor(fan), tick);
        }
    }

    public void setContext(String name, String equipment) {
        setContext(FanChatContext.idle(name, equipment));
    }

    public void setContext(FanChatContext context) {
        this.context = context;
    }

    private String personalize(String quote) {
        if (quote == null) return null;
        String result =
                quote.replace("{player}", context.player.isEmpty() ? "you" : context.player)
                        .replace("{gear}", context.gear.isEmpty() ? "fit" : context.gear)
                        .replace("{target}", context.target.isEmpty() ? "opponent" : context.target)
                        .replace(
                                "{skill}",
                                context.skill == null ? "skill" : context.skill.getName())
                        .replace("{level}", Integer.toString(context.level));
        return result.substring(0, Math.min(100, result.length()));
    }

    public void level(List<FanEntity> fans, int tick, net.runelite.api.Skill skill, int level) {
        FanChatContext event =
                new FanChatContext(
                        context.player,
                        context.gear,
                        context.target,
                        context.activity,
                        skill,
                        level,
                        0,
                        false,
                        false);
        FanChatContext previous = context;
        context = event;
        try {
            reactGenerated(fans, tick, () -> FanDialogueGenerator.level(event, random));
        } finally {
            context = previous;
        }
    }

    private String signature(String line) {
        String normalized = line.toLowerCase(Locale.ENGLISH);
        if (!context.player.isEmpty()) normalized = normalized.replace(context.player.toLowerCase(Locale.ENGLISH), "");
        normalized = normalized.replaceAll("\\b(ur)\\b", "your")
                .replaceAll("\\b(u)\\b", "you");
        return SPACES.matcher(PUNCTUATION.matcher(normalized).replaceAll(""))
                .replaceAll(" ").trim();
    }

    private FanUtterance chooseFor(FanEntity fan) {
        if (mode == CustomQuoteMode.CUSTOM_ONLY
                || (mode == CustomQuoteMode.MIXED && !custom.isEmpty() && random.nextInt(3) == 0))
            return new FanUtterance(choose(custom), null);
        FanUtterance best = null;
        int bestPenalty = Integer.MAX_VALUE;
        int lengthRoll = random.nextInt(100);
        // Evaluate a bounded set of candidates, preferring new wording AND new structure.
        for (int attempt = 0; attempt < 48; attempt++) {
            FanUtterance candidate = FanDialogueGenerator.generateUtterance(random, fan.personality, context, lengthRoll);
            String key = signature(candidate.text);
            int penalty = recentCrowd.contains(key) ? 8 : 0;
            if (recentFans.get(fan) != null && recentFans.get(fan).contains(key)) penalty += 12;
            if (recentStructures.contains(candidate.structure)) penalty += 4;
            if (fanStructures.get(fan) != null && fanStructures.get(fan).contains(candidate.structure)) penalty += 6;
            for (Map.Entry<FanEntity, String> entry : visibleStructures.entrySet()) {
                FanEntity other = entry.getKey();
                if (other != fan && other.overheadText != null && other.isVisible()
                        && candidate.text.length() > 40 && candidate.structure.equals(entry.getValue()))
                    penalty += 10;
            }
            if (candidate.text.equals(lastQuote)) penalty += 20;
            if (penalty < bestPenalty) {
                best = candidate;
                bestPenalty = penalty;
            }
            if (penalty == 0) break;
        }
        lastQuote = best.text;
        return best;
    }

    public String choose(List<String> pool) {
        if (pool == null || pool.isEmpty()) return null;
        List<String> candidates = new ArrayList<>();
        for (String q : pool) if (!personalize(q).equals(lastQuote)) candidates.add(personalize(q));
        String quote =
                candidates.isEmpty()
                        ? personalize(pool.get(0))
                        : candidates.get(random.nextInt(candidates.size()));
        lastQuote = quote;
        return quote;
    }

    public void reactEvent(List<FanEntity> fans, int tick, String event) {
        reactGenerated(fans, tick, () -> FanDialogueGenerator.event(event, context, random));
    }

    public void react(List<FanEntity> fans, int tick, String[] quotes) {
        reactGenerated(fans, tick, () -> choose(Arrays.asList(quotes)));
    }

    private void reactGenerated(List<FanEntity> fans, int tick, java.util.function.Supplier<String> generate) {
        if (frequency == ChatFrequency.OFF || fans.isEmpty()
                || (mode == CustomQuoteMode.CUSTOM_ONLY && custom.isEmpty())) return;
        int start = random.nextInt(fans.size());
        for (int i = 0; i < Math.min(2, fans.size()); i++) {
            FanEntity fan = fans.get((start + i) % fans.size());
            if (fan.isVisible()) {
                say(fan, mode == CustomQuoteMode.CUSTOM_ONLY ? choose(custom) : generate.get(), tick);
                fan.nextChatTick = Math.max(fan.nextChatTick, tick + 3);
            }
        }
    }

    private void say(FanEntity fan, String quote, int tick) {
        say(fan, new FanUtterance(quote, null), tick);
    }

    private void say(FanEntity fan, FanUtterance utterance, int tick) {
        String quote = utterance.text;
        if (utterance.structure != null && quote != null) {
            remember(recentStructures, utterance.structure, 16);
            remember(fanStructures.computeIfAbsent(fan, ignored -> new ArrayDeque<>()), utterance.structure, 6);
            visibleStructures.put(fan, utterance.structure);
        } else visibleStructures.remove(fan);
        if (quote != null) {
            String key = signature(quote);
            remember(recentCrowd, key, 96);
            Deque<String> personal = recentFans.computeIfAbsent(fan, ignored -> new ArrayDeque<>());
            remember(personal, key, 16);
            fan.overheadText = quote;
            fan.overheadExpiryTick = tick + 5 + quote.length() / 12 + random.nextInt(4);
            // Roughly 40–80 words/minute, plus thinking time, consistent for each sender.
            int typingTicks = (quote.length() + 1) / (2 + Math.floorMod(fan.id, 3));
            fan.nextChatTick = Math.max(fan.nextChatTick,
                    tick + Math.max(4, typingTicks) + 2 + random.nextInt(5));
        }
    }

    private static void remember(Deque<String> history, String value, int limit) {
        history.addLast(value);
        if (history.size() > limit) history.removeFirst();
    }

    String visibleStructure(FanEntity fan) { return visibleStructures.get(fan); }

    public void clear(List<FanEntity> fans) {
        for (FanEntity f : fans) {
            f.overheadText = null;
            f.nextChatTick = 0;
        }
        lastQuote = null;
        recentCrowd.clear();
        recentFans.clear();
        recentStructures.clear();
        fanStructures.clear();
        visibleStructures.clear();
        nextTick = Integer.MAX_VALUE;
    }
}

package com.celebritymode.chat;

import com.celebritymode.fan.FanPersonality;
import com.celebritymode.generation.ConversationComposer;
import com.celebritymode.generation.FanUtterance;
import com.celebritymode.generation.QuickChatComposer;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Context-selected patterns composed with conversational fragments, rather than fixed quotes. */
public final class FanDialogueGenerator {
    private static final Map<String, List<String>> PATTERNS = load();
    private static final String[] GREETINGS = {
        "yo",
        "hey",
        "oh hey",
        "wait",
        "omg",
        "no way",
        "hold up",
        "ay",
        "look who it is",
