    };
    private static final String[] PRAISE = {
        "clean",
        "goated",
        "huge",
        "insane",
        "unreal",
        "actually sick",
        "looking good",
        "solid",
        "proper nice",
        "impressive",
        "a vibe",
        "next level"
    };
    private static final String[] REQUESTS = {
        "add me",
        "teach me your ways",
        "say hi to the cc",
        "raid with us",
        "join the clan",
        "share the secret",
        "give us a tip",
        "save me a spot",
        "show me your setup",
        "come on a boss trip"
    };
    private static final String[] ACTIVITIES = {
        "toa",
        "tob",
        "cox",
        "a boss trip",
        "a duo",
        "a quest",
        "a chill slayer trip",
        "a minigame",
        "a clan event",
        "some pvm",
        "a wildy trip"
    };
    private static final String[] GOALS = {
        "99",
        "pet",
        "gear upgrade",
        "diary",
        "collection log slot",
        "combat achievement",
        "quest",
        "skill milestone",
        "personal best",
        "cape"
    };
    private static final String[] SUPPLIES = {
        "staminas", "food", "teleports", "restores", "prayer pots", "runes", "bonds", "advice"
    };
    private static final String[] ENDINGS = {" lol", " haha", " pls", " :)", " fr", "", "", "", ""};

    private FanDialogueGenerator() {}

    public static String generate(
            Random random, FanPersonality personality, String name, String gear) {
        return generate(random, personality, FanChatContext.idle(name, gear));
    }

    public static String generate(
            Random random, FanPersonality personality, FanChatContext context) {
        return generateUtterance(random, personality, context).text;
    }

    public static FanUtterance generateUtterance(
            Random random, FanPersonality personality, FanChatContext context) {
        return generateUtterance(random, personality, context, random.nextInt(100));
    }

    static FanUtterance generateUtterance(
            Random random, FanPersonality personality, FanChatContext context, int lengthRoll) {
        String category;
        int roll = random.nextInt(100);
        if (context.lowHealth && roll < 20) category = "low_health";
        else if (context.gearChanged && roll < 30) category = "gear_change";
        else if (!context.gear.isEmpty() && roll >= 90) category = "gear";
        else if (roll < 65) {
            category = context.activity.name().toLowerCase(Locale.ENGLISH);
            if (context.activity == FanChatContext.Activity.SKILLING
                    && context.skill != null
                    && random.nextInt(3) != 0) {
                String specific = context.skill.name().toLowerCase(Locale.ENGLISH);
                if (PATTERNS.containsKey(specific)) category = specific;
            }
            if (context.activity == FanChatContext.Activity.COMBAT
                    && !context.target.isEmpty()
                    && random.nextInt(4) != 0) category = "combat_target";
        } else
            category =
                    random.nextBoolean()
                            ? "social"
                            : personality.name().toLowerCase(Locale.ENGLISH);
        if (lengthRoll >= 90) return lineUtterance(category, context, random, true);
        return QuickChatComposer.generate(random, personality.name(), context.player, category,
                context.gear.toLowerCase(Locale.ENGLISH), context.target,
                context.skill == null ? "" : context.skill.getName().toLowerCase(Locale.ENGLISH),
                lengthRoll < 80);
    }

    public static String level(FanChatContext context, Random random) {
        if (random.nextInt(5) == 0) return line("level", context, random, false);
        String skill = context.skill == null ? "skill" : context.skill.getName().toLowerCase(Locale.ENGLISH);
        String body = pick(new String[] {"gz on ", "nice, ", "congrats on ", "well played, ", "good progress, "}, random)
                + context.level + " " + skill + pick(new String[] {"", "!", ", well earned",
                    ". good luck with the next goal", ". how long did that take?", ", nice milestone",
                    ". another level done", ", keep it going", ". worth the time", ", solid session"}, random);
        String addressed = context.player.isEmpty() ? body : context.player + ", " + body;
        return ConversationComposer.style(random, "", addressed, 100);
    }

    public static String event(String event, FanChatContext context, Random random) {
        if (random.nextInt(5) == 0) return line(event, context, random, false);
        if (event.equals("recognition"))
            return QuickChatComposer.generate(random, "EXCITED", context.player, "social",
                    "", "", "", true).text;
        String body = event.equals("death")
                ? pick(new String[] {"rip", "bro unlucky", "ah nooo", "rough one", "go again",
                    "F", "so close", "unlucky", "rip supplies", "noooo"}, random)
                : pick(new String[] {"gz", "huge", "let's go", "nice", "well played",
                    "big gz", "clean", "goated", "we take those", "let's gooo"}, random);
        return random.nextBoolean() && !context.player.isEmpty() ? body + " " + context.player : body;
    }

    private static String line(
            String category, FanChatContext context, Random random, boolean decorate) {
        return lineUtterance(category, context, random, decorate).text;
    }

    private static FanUtterance lineUtterance(
            String category, FanChatContext context, Random random, boolean decorate) {
        List<String> valid = new ArrayList<>();
        for (String pattern : PATTERNS.getOrDefault(category, PATTERNS.get("social"))) {
            if (pattern.contains("{level}") && context.level <= 0
                    || pattern.contains("{xp}") && context.gainedXp <= 0
                    || pattern.contains("{skill}") && context.skill == null) continue;
            valid.add(pattern);
        }
        if (valid.isEmpty()) valid = PATTERNS.get("social");
        String pattern = valid.get(random.nextInt(valid.size()));
        String result =
                pattern
                        .replace("{player}", context.player.isEmpty() ? "friend" : context.player)
                        .replace(
                                "{gear}",
                                context.gear.isEmpty()
                                        ? "fit"
                                        : context.gear.toLowerCase(Locale.ENGLISH))
                        .replace("{target}", context.target)
                        .replace(
                                "{skill}",
                                context.skill == null
                                        ? "skill"
                                        : context.skill.getName().toLowerCase(Locale.ENGLISH))
                        .replace("{level}", Integer.toString(context.level))
                        .replace("{xp}", Integer.toString(context.gainedXp))
                        .replace("{greeting}", pick(GREETINGS, random))
                        .replace("{praise}", pick(PRAISE, random))
                        .replace("{request}", pick(REQUESTS, random))
                        .replace("{activity}", pick(ACTIVITIES, random))
                        .replace("{goal}", pick(GOALS, random))
                        .replace("{supply}", pick(SUPPLIES, random));
        if (decorate && random.nextInt(7) == 0) result = pick(GREETINGS, random) + ", " + result;
        if (decorate && random.nextInt(5) == 0 && !result.endsWith("?"))
            result += pick(ENDINGS, random);
        if (decorate && random.nextInt(24) == 0) result = result.toUpperCase(Locale.ENGLISH);
        return new FanUtterance(result.substring(0, Math.min(100, result.length())), pattern);
    }

    private static String pick(String[] options, Random random) {
        return options[random.nextInt(options.length)];
    }

    private static Map<String, List<String>> load() {
        Map<String, List<String>> result = new HashMap<>();
        try (BufferedReader reader =
                new BufferedReader(
                        new InputStreamReader(
                                Objects.requireNonNull(
                                        FanDialogueGenerator.class.getResourceAsStream(
                                                "dialogue.txt")),
                                StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] entry = line.split("\\|", 2);
                if (entry.length != 2) throw new IOException("Invalid dialogue pattern");
                result.computeIfAbsent(entry[0], key -> new ArrayList<>()).add(entry[1]);
            }
        } catch (IOException ex) {
            throw new IllegalStateException("Unable to load fan dialogue", ex);
        }
        return result;
    }
}

package com.celebritymode.chat;

import java.util.*;

public final class FanQuoteLibrary {
    private FanQuoteLibrary() {}

    public static List<String> parse(String input) {
        if (input == null || input.trim().isEmpty()) return Collections.emptyList();
        String[] parts =
                input.split(input.contains("\n") || input.contains("\r") ? "\r\n|[\r\n]" : ",");
        List<String> result = new ArrayList<>();
        for (String s : parts) {
            String clean = s.replaceAll("<[^>]*>", "").trim();
            if (!clean.isEmpty()) result.add(clean.substring(0, Math.min(100, clean.length())));
            if (result.size() == 100) break;
        }
        return Collections.unmodifiableList(result);
    }

}

package com.celebritymode.fan;

public enum ArrivalPace {
    GRADUAL,
    QUICK,
    INSTANT;

    public int dueTick(int startTick, int ordinal) {
        int delay = CrowdArrival.dueTick(0, ordinal);
        return startTick + (this == INSTANT ? 0 : this == QUICK ? Math.max(1, delay / 4) : delay);
    }
}

package com.celebritymode.fan;

/**
 * Word-of-mouth fan arrivals in OSRS game ticks (600ms). A spotter alerts two friends, then
 * branching waves build larger crowds without spawning everyone at once.
 */
public final class CrowdArrival {
    public static final int MAX_FANS = 100;
    private static final int INITIAL_SPOT_TICKS = 4;
    private static final int TICKS_PER_GENERATION = 16;
    private static final int MAX_JITTER_TICKS = 2;

    private CrowdArrival() {}

    public static int dueTick(int startTick, int ordinal) {
        if (ordinal < 0 || ordinal >= MAX_FANS) {
            throw new IllegalArgumentException(
                    "Fan ordinal must be between 0 and " + (MAX_FANS - 1));
        }
        if (ordinal == 0) return startTick + INITIAL_SPOT_TICKS;

        // floor(log2(ordinal + 1)): generations contain 1, 2, 4, 8, 16, 32, then the remaining fans.
        int generation = 31 - Integer.numberOfLeadingZeros(ordinal + 1);
        int genStart = (1 << generation) - 1;
        int genSize = 1 << generation;
        double progressInGen = (double) (ordinal - genStart) / genSize;
        int waveOffset = (int) Math.round(progressInGen * (TICKS_PER_GENERATION - 2));
        int baseDelay = INITIAL_SPOT_TICKS + generation * TICKS_PER_GENERATION + waveOffset;
        int jitter = pseudoJitter(ordinal, MAX_JITTER_TICKS);
        return startTick + Math.max(INITIAL_SPOT_TICKS + 1, baseDelay + jitter);
    }

    /** Stable pathing/reaction variance without consuming the crowd's shared random state. */
    private static int pseudoJitter(int seed, int range) {
        int hash = (seed * 0x45d9f3b) ^ (seed >> 8);
        hash = (hash * 0x45d9f3b) ^ (hash >> 16);
        // Widen before abs so Integer.MIN_VALUE cannot produce out-of-range jitter.
        return (int) (Math.abs((long) hash) % (range * 2 + 1)) - range;
    }
}

package com.celebritymode.fan;

import java.util.Random;

/** Slow, bounded turnover; scene loading does not restart the attendance clock. */
public final class CrowdPopulation {
    private int maximum, attendance, target, nextSurvey, nextChange;

    public int update(int tick, int configuredMaximum, int nearbyPlayers, int hour, Random random) {
        int cap = Math.max(1, Math.min(CrowdArrival.MAX_FANS, configuredMaximum));
        if (cap != maximum) {
            maximum = cap;
            attendance = target = cap;
            nextSurvey = tick + 600; // Let the entrance finish and the crowd settle first.
            nextChange = nextSurvey;
        }
        if (tick >= nextSurvey) {
            int range = Math.min(cap - 1, Math.max(1, (int) Math.ceil(cap * 0.08)));
            // Nearby real players are a local activity proxy, not a world population census.
            double activity = Math.min(1, Math.max(0, nearbyPlayers) / 40.0);
            double evening = (1 + Math.cos((hour - 20) * Math.PI / 12)) / 2;
            int missing = (int) Math.round(range *
                    (0.25 * (1 - activity) + 0.20 * (1 - evening) + 0.55 * random.nextDouble()));
            target = Math.max(1, cap - missing);
            nextSurvey = tick + 200 + random.nextInt(300);
        }
        if (tick >= nextChange) {
            attendance += Integer.signum(target - attendance);
            nextChange = tick + 60 + random.nextInt(100);
        }
        return attendance;
    }

    public void clear() {
        maximum = 0;
    }
}

package com.celebritymode.fan;

import net.runelite.api.*;
import net.runelite.api.gameval.AnimationID;

import java.util.*;

import javax.inject.*;

/** Named IDs from the current cache's generated gameval definitions. */
@Singleton
public final class FanAnimations {
    private final Client client;
    private final Map<Integer, Animation> resources = new HashMap<>();

    @Inject
    public FanAnimations(Client client) {
        this.client = client;
    }

    public void setState(FanEntity fan, FanState state) {
        if (fan.object == null || fan.state == state) return;
        fan.state = state;
        String weapon = fan.appearance == null ? "" : fan.appearance.weaponName;
        boolean whip = weapon.contains("whip"),
                staff =
                        weapon.contains("staff")
                                || weapon.contains("wand")
                                || weapon.contains("sceptre");
        boolean pole =
                weapon.contains("spear") || weapon.contains("lance") || weapon.contains("halberd");
        int id;
        if (state == FanState.RUNNING)
            id =
                    whip
                            ? AnimationID.SLAYER_ABYSSAL_WHIP_RUN
                            : pole ? AnimationID.HUMAN_HALBERDRUNNING : AnimationID.HUMAN_RUNNING;
        else if (state == FanState.WALKING)
            id =
                    whip
                            ? AnimationID.SLAYER_ABYSSAL_WHIP_WALK
                            : pole ? AnimationID.HUMAN_HALBERDWALK_F : AnimationID.HUMAN_WALK_F;
        else
            id =
                    staff
                            ? AnimationID.HUMAN_STAFFREADY
                            : pole ? AnimationID.HUMAN_ZAMORAKSPEAR_READY : AnimationID.HUMAN_READY;
        play(fan, id, false);
    }

    public void react(FanEntity fan, boolean cheer) {
        if (fan.object == null || fan.state != FanState.IDLE) return;
        fan.state = FanState.REACTION;
        play(fan, cheer ? AnimationID.EMOTE_CHEER : AnimationID.EMOTE_WAVE, true);
    }

    private void play(FanEntity fan, int id, boolean oneShot) {
        Animation resource = resources.computeIfAbsent(id, client::loadAnimation);
        if (resource == null) {
            fan.state = FanState.IDLE;
            return;
        }
        if (fan.animation == null) {
            fan.animation = new AnimationController(client, resource);
            fan.object.setAnimationController(fan.animation);
        } else fan.animation.setAnimation(resource);
        fan.animation.setOnFinished(
                oneShot
                        ? ac -> {
                            if (fan.state == FanState.REACTION && fan.object != null)
                                setState(fan, FanState.IDLE);
                        }
                        : AnimationController::loop);
    }

    public void clear() {
        resources.clear();
    }
}

package com.celebritymode.fan;

import com.celebritymode.appearance.FanAppearance;

import net.runelite.api.*;
import net.runelite.api.coords.*;

/** Mutable only on the client thread; painting only reads the getters. */
public final class FanEntity {
    public final int id;
    public final FanPersonality personality;
    public final String displayName;
    public final int trailOffset, lateralBias, tileJitterX, tileJitterY;
    public int formationSlot, overheadExpiryTick, movementStartCycle, stalledTicks;
    public int orientation, targetOrientation;
    public int arrivalTick = Integer.MAX_VALUE, nextWanderTick, nextChatTick;
    public boolean arrived;
    public WorldPoint idleTarget, followTarget;
    public FanState state = FanState.DESPAWNED;
    public FanAppearance appearance;
    public RuneLiteObject object;
    public Model model;
    public AnimationController animation;
    public WorldPoint position, target;
    public LocalPoint renderLocation;
    public LocalPoint[] movementPath;
    public String overheadText;

    public FanEntity(int id, FanPersonality personality, String name, int delay, int bias) {
        this.id = id;
        this.personality = personality;
        displayName = name;
        trailOffset = delay;
        lateralBias = bias;
        tileJitterX = Math.floorMod(id * 37 + 11, 55) - 27;
        tileJitterY = Math.floorMod(id * 19 + 31, 55) - 27;
        formationSlot = id;
    }

    public void deactivate() {
        if (object != null) object.setActive(false);
        object = null;
        animation = null;
        renderLocation = null;
        movementPath = null;
        position = null;
        target = null;
        state = FanState.DESPAWNED;
        overheadText = null;
        stalledTicks = 0;
        idleTarget = null;
        followTarget = null;
        nextChatTick = 0;
    }

    public LocalPoint getRenderLocation() {
        return renderLocation;
    }

    public boolean isVisible() {
        return object != null && object.isActive() && renderLocation != null;
    }
}

package com.celebritymode.fan;

import com.celebritymode.CelebrityModeConfig;
import com.celebritymode.appearance.*;
import com.celebritymode.chat.*;
import com.celebritymode.movement.*;
import com.celebritymode.generation.UsernameGenerator;
import com.celebritymode.util.OrientationUtil;

import net.runelite.api.*;
import net.runelite.api.coords.*;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.LocalTime;
import java.util.*;

import javax.inject.*;

@Singleton
public final class FanManager {
    private static final Logger log = LoggerFactory.getLogger(FanManager.class);
    private final Client client;
    private final CelebrityModeConfig config;
    private final Random random;
    private final FanAppearanceFactory appearances;
    private final FanModelFactory models;
    private final CollisionService collision;
    private final FormationPlanner formations;
    private final FanMovementController movement;
    private final FanAnimations animations;
    private final FanChatManager chat;
    private final FanActivityTracker activity = new FanActivityTracker();
    private final List<FanEntity> fans = new ArrayList<>();
    private final List<FanEntity> readOnlyFans = Collections.unmodifiableList(fans);
    private final MovementTrail trail = new MovementTrail();
    private final CrowdPopulation population = new CrowdPopulation();
    private WorldView view;
    private WorldPoint previous;
    private int worldViewId,
            baseX,
            baseY,
            plane,
            dx = 0,
            dy = 1,
            tick,
            stationaryTicks,
            nextId,
            retryAfter,
            lastRecognition = -1000;
    private int lastEventReaction = -1000;
    private int nextCrowdEmoteTick;
    private boolean recognitionPending, sceneSuspended, instanced;
    private int instanceLayout;

    @Inject
    public FanManager(
            Client client,
            CelebrityModeConfig config,
            Random random,
            FanAppearanceFactory appearances,
            FanModelFactory models,
            CollisionService collision,
            FormationPlanner formations,
            FanMovementController movement,
            FanAnimations animations) {
        this.client = client;
        this.config = config;
        this.random = random;
        this.appearances = appearances;
        this.models = models;
        this.collision = collision;
        this.formations = formations;
        this.movement = movement;
        this.animations = animations;
        chat = new FanChatManager(random);
    }

    public List<FanEntity> getFans() {
        return readOnlyFans;
    }

    public List<WorldPoint> getBreadcrumbs() {
        return trail.snapshot();
    }

    public WorldView getView() {
        return view;
    }

    public void initialize(Player player) {
        onGameTick(player);
    }

    public void onGameTick(Player player) {
        tick++;
        if (!config.showCrowd()) {
            if (view != null) resetScene();
            return;
        }
        if (client.getGameState() == GameState.LOADING) {
            suspendScene();
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            resetScene();
            return;
        }
        if (player == null) {
            suspendScene();
            return;
        }
        LocalPoint local = player.getLocalLocation();
        WorldView current = local == null ? null : client.getWorldView(local.getWorldView());
        if (current == null || current.getCollisionMaps() == null) {
            suspendScene();
            return;
        }
        WorldPoint point =
                WorldPoint.fromLocal(current, local.getX(), local.getY(), current.getPlane());
        boolean baseMoved = current.getBaseX() != baseX || current.getBaseY() != baseY;
        int layout =
                current.isInstance() ? Arrays.deepHashCode(current.getInstanceTemplateChunks()) : 0;
        boolean changed =
                view == null
                        || current.getId() != worldViewId
                        || current.getPlane() != plane
                        || current.isInstance() != instanced
                        || (previous != null && previous.distanceTo(point) > 8)
                        || (instanced && !baseMoved && layout != instanceLayout);
        if (!changed && (sceneSuspended || baseMoved || current != view)) rebaseScene(current);
        if (changed) {
            resetScene();
            view = current;
            worldViewId = view.getId();
            baseX = view.getBaseX();
            baseY = view.getBaseY();
            plane = view.getPlane();
            instanced = view.isInstance();
            instanceLayout = layout;
            collision.bind(view);
            configureChat();
            nextCrowdEmoteTick = tick + 100 + random.nextInt(140);
            recognitionPending = true;
        }
        instanceLayout = layout;
        boolean running = false;
        if (previous != null && !previous.equals(point)) {
            dx = Integer.signum(point.getX() - previous.getX());
            dy = Integer.signum(point.getY() - previous.getY());
            running = previous.distanceTo(point) >= 2;
            // Fill a two-tile running breadcrumb only when the intermediate route passes collision
            // checks.
            WorldPoint middle = FormationPlanner.offset(previous, dx, dy);
            if (running && collision.canStep(previous, middle) && collision.canStep(middle, point))
                trail.update(middle);
            stationaryTicks = 0;
            for (FanEntity fan : fans) {
                fan.idleTarget = null;
                fan.followTarget = null;
            }
        } else stationaryTicks++;
        trail.update(point);
        previous = point;
        String equipped = "";
        PlayerComposition composition = player.getPlayerComposition();
        if (composition != null) {
            int weapon = composition.getEquipmentId(net.runelite.api.kit.KitType.WEAPON);
            if (weapon >= 0) equipped = client.getItemDefinition(weapon).getName();
        }
        chat.setContext(
                activity.observe(client, player, equipped, stationaryTicks == 0, running, tick));
        appearances.advanceCatalog();
        resizeCrowd(
                population.update(
                        tick, config.crowdSize(), nearbyPlayers(current),
                        LocalTime.now().getHour(), random));
        if (changed)
            for (int i = 0; i < fans.size(); i++) {
                FanEntity fan = fans.get(i);
                fan.arrived = false;
                fan.arrivalTick = config.arrivalPace().dueTick(tick, i);
            }
        boolean stopped = stationaryTicks >= 25;
        Set<WorldPoint> reserved = new HashSet<>();
        for (FanEntity fan : fans) if (fan.position != null) reserved.add(fan.position);
        for (FanEntity fan : fans) {
            if (!fan.arrived && tick < fan.arrivalTick) continue;
            if (fan.position != null) reserved.remove(fan.position);
            boolean gathering = formations.shouldGather(fan, stationaryTicks);
            WorldPoint target;
            if (fan.state == FanState.REACTION && stationaryTicks > 0) {
                target = fan.position;
            } else if (gathering) {
                target = formations.chooseIdleTarget(fan, point, reserved, random, tick);
            } else if (stationaryTicks > 20 && fan.followTarget != null
                    && collision.canOccupy(fan.followTarget)) {
                target = fan.followTarget;
            } else {
                target = formations.chooseTarget(
                        fan, point, dx, dy, trail, reserved, stationaryTicks);
            }
            if (!gathering && fan.state != FanState.REACTION) fan.followTarget = target;
            if (target != null) reserved.add(target);
            if (fan.object == null
                    || !fan.object.isActive()
                    || fan.position == null
                    || LocalPoint.fromWorld(view, fan.position) == null
                    || fan.position.distanceTo(point) > 45
                    || fan.stalledTicks > 20
                    || (target != null && fan.position.distanceTo(target) > 24)) {
                if (tick < retryAfter) continue;
                try {
                    WorldPoint spawnPoint =
                            fan.arrived
                                    ? target
                                    : formations.chooseArrivalPoint(fan, point, target, reserved);
                    spawn(fan, spawnPoint);
                    if (fan.object != null) fan.arrived = true;
                } catch (RuntimeException ex) {
                    fan.deactivate();
                    retryAfter = tick + 5;
                    log.debug("Fan {} awaiting available cache/scene resources", fan.id, ex);
                }
                continue;
            }
            movement.render(fan, view, client.getGameCycle());
            movement.plan(fan, target, trail, running, view, client.getGameCycle(), gathering);
            if (fan.state == FanState.IDLE || fan.state == FanState.REACTION) {
                if (fan.id % 5 != 0)
                    fan.targetOrientation =
                            OrientationUtil.facing(
                                    point.getX() - fan.position.getX(),
                                    point.getY() - fan.position.getY());
            }
        }
        if (stopped && config.reactToEvents() && tick >= nextCrowdEmoteTick) {
            List<FanEntity> idle = new ArrayList<>();
            for (FanEntity fan : fans)
                if (fan.isVisible()
                        && fan.state == FanState.IDLE
                        && fan.movementPath == null
                        && fan.personality != FanPersonality.QUIET) idle.add(fan);
            if (!idle.isEmpty()) {
                FanEntity fan = idle.get(random.nextInt(idle.size()));
                animations.react(fan, random.nextBoolean());
                nextCrowdEmoteTick = tick + 100 + random.nextInt(140);
            }
        }
        chat.tick(fans, tick);
        if (recognitionPending && fans.stream().anyMatch(FanEntity::isVisible)) {
            if (config.reactToEvents() && tick - lastRecognition > 100) {
                chat.reactEvent(fans, tick, "recognition");
                lastRecognition = tick;
            }
            recognitionPending = false;
        }
    }

    private int nearbyPlayers(WorldView current) {
        if (current.players() == null) return 0;
        int count = 0;
        for (Player ignored : current.players()) if (++count >= 40) break;
        return count;
    }

    private void spawn(FanEntity fan, WorldPoint point) {
        fan.deactivate();
        if (point == null || !collision.canOccupy(point)) return;
        LocalPoint local = LocalPoint.fromWorld(view, point);
        if (local == null) return;
        if (fan.appearance == null)
            fan.appearance = appearances.createAppearance(fan.id, config.crowdGearTier());
        if (fan.model == null) fan.model = models.createModel(fan.appearance);
        Model model = fan.model;
        if (model == null) throw new IllegalStateException("Missing fan model");
        fan.object = client.createRuneLiteObject();
        fan.object.setModel(model);
        fan.renderLocation = local.plus(fan.tileJitterX, fan.tileJitterY);
        fan.position = point;
        fan.target = point;
        fan.orientation =
                fan.targetOrientation =
                        OrientationUtil.facing(
                                previous == null ? 0 : previous.getX() - point.getX(),
                                previous == null ? 1 : previous.getY() - point.getY());
        fan.object.setLocation(fan.renderLocation, plane);
        fan.object.setOrientation(fan.orientation);
        animations.setState(fan, FanState.IDLE);
        fan.nextWanderTick = tick + 100 + random.nextInt(200);
        fan.object.setActive(true);
    }

    public void onClientTick() {
        if (!config.showCrowd()) {
            if (view != null) resetScene();
            return;
        }
        Player player = client.getLocalPlayer();
        if (client.getGameState() == GameState.LOADING) {
            suspendScene();
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            resetScene();
            return;
        }
        if (player == null) {
            suspendScene();
            return;
        }
        LocalPoint point = player.getLocalLocation();
        if (view == null) return;
        if (point == null
                || client.getWorldView(point.getWorldView()) != view
                || point.getWorldView() != worldViewId
                || view.getBaseX() != baseX
                || view.getBaseY() != baseY
                || view.getPlane() != plane) {
            suspendScene();
            return; // GameTick classifies relocation against preserved world positions.
        }
        if (sceneSuspended) return;
        for (FanEntity fan : fans)
            if (fan.isVisible()) movement.render(fan, view, client.getGameCycle());
    }

    public void resizeCrowd(int size) {
        int desired = Math.max(1, Math.min(CrowdArrival.MAX_FANS, size));
        while (fans.size() > desired) fans.remove(random.nextInt(fans.size())).deactivate();
        int arrivalOrdinal = 0;
        while (fans.size() < desired) {
            int id = nextId++;
            Set<String> excluded = new HashSet<>();
            for (FanEntity existing : fans) excluded.add(existing.displayName);
            Player player = client.getLocalPlayer();
            if (player != null) excluded.add(player.getName());
            String name = UsernameGenerator.generate(random, excluded);
            fans.add(
                    new FanEntity(
                            id,
                            FanPersonality.values()[random.nextInt(FanPersonality.values().length)],
                            name,
                            1 + random.nextInt(10),
                            random.nextInt(3) - 1));
            fans.get(fans.size() - 1).arrivalTick = config.arrivalPace().dueTick(tick, arrivalOrdinal++);
        }
        formations.reassignSlots(fans);
    }

    public void rebuildAppearances() {
        for (FanEntity fan : fans) {
            fan.deactivate();
            fan.appearance = null;
            fan.model = null;
        }
        retryAfter = 0;
    }

    public void onConfigChanged(String key) {
        switch (key) {
            case "showCrowd":
                if (!config.showCrowd()) resetScene();
                break;
            case "crowdSize":
                population.clear();
                resizeCrowd(config.crowdSize());
                break;
            case "crowdGearTier":
                rebuildAppearances();
                break;
            case "formationStyle":
                formations.reassignSlots(fans);
                // Settled followers must apply layout changes even before the player moves.
            case "maxSpread":
            case "respectPersonalSpace":
                for (FanEntity fan : fans) {
                    fan.followTarget = null;
                    fan.idleTarget = null;
                }
                break;
            case "chatFrequency":
            case "customQuotes":
            case "customQuoteMode":
                chat.clear(fans);
                configureChat();
                break;
            default:
                break; // Other preferences are read on the next tick/paint.
        }
    }

    private void configureChat() {
        chat.configure(
                config.chatFrequency(), config.customQuoteMode(), config.customQuotes(), tick);
    }

    public void onExperience(Skill skill, int xp) {
        activity.experience(skill, xp, tick);
    }

    public void onMenuOption(String option) {
        activity.menu(option, tick);
    }

    public void reactLevel(Skill skill, int level) {
        if (!config.showCrowd() || !config.reactToEvents() || tick - lastEventReaction < 3) return;
        lastEventReaction = tick;
        chat.level(fans, tick, skill, level);
    }

    public void react(boolean death) {
        if (!config.showCrowd() || !config.reactToEvents() || tick - lastEventReaction < 3) return;
        lastEventReaction = tick;
        chat.reactEvent(fans, tick, death ? "death" : "achievement");
    }

    public void onGameStateChanged(GameState state) {
        if (state == GameState.LOADING) suspendScene();
        else if (state != GameState.LOGGED_IN) resetScene();
    }

    /** Ordinary map loading unregisters objects but keeps route, models, and arrival progress. */
    private void suspendScene() {
        if (sceneSuspended) return;
        for (FanEntity fan : fans) {
            if (fan.object != null) fan.object.setActive(false);
            fan.renderLocation = null;
            fan.movementPath = null;
        }
        sceneSuspended = true;
    }

    private void rebaseScene(WorldView current) {
        suspendScene();
        view = current;
        worldViewId = view.getId();
        baseX = view.getBaseX();
        baseY = view.getBaseY();
        plane = view.getPlane();
        collision.bind(view);
        for (FanEntity fan : fans)
            if (fan.object != null && fan.position != null) {
                LocalPoint local = LocalPoint.fromWorld(view, fan.position);
                if (local == null) continue; // Only this follower needs a bounded local repair.
                fan.renderLocation = local.plus(fan.tileJitterX, fan.tileJitterY);
                fan.object.setLocation(fan.renderLocation, plane);
                fan.object.setActive(true);
                animations.setState(fan, FanState.IDLE);
            }
        sceneSuspended = false;
    }

    public void resetScene() {
        for (FanEntity fan : fans) {
            fan.deactivate();
            fan.arrived = false;
            fan.arrivalTick = Integer.MAX_VALUE;
        }
        trail.clear();
        activity.clear();
        chat.clear(fans);
        previous = null;
        view = null;
        sceneSuspended = false;
        collision.bind(null);
        stationaryTicks = 0;
        recognitionPending = false;
        retryAfter = 0;
    }

    public void cleanup() {
        resetScene();
        fans.clear();
        models.clear();
        appearances.clear();
        animations.clear();
        population.clear();
        nextId = 0;
        tick = 0;
        lastRecognition = -1000;
        lastEventReaction = -1000;
    }
}

