        "Chris", "Jules", "Theo", "Maya", "Nina", "Leo", "Eli", "Zoe", "Noah", "Milo",
        "Iris", "Owen", "Ari", "Remy", "Sasha", "Luca", "Anya", "Erin", "Drew", "Ellis"
    };
    private static final String[] START = {"al", "bel", "cor", "dar", "el", "fen", "hal", "is", "jor", "kel", "lin", "mar", "nor", "or", "per", "ren", "sol", "tal", "val", "wyn"};
    private static final String[] MIDDLE = {"a", "e", "i", "o", "u", "an", "en", "in", "or", "ar", "el", "ir"};
    private static final String[] END = {"n", "s", "th", "ra", "ro", "len", "lis", "vin", "wen", "ric", "rin", "dor", "na", "lo", "mi", "den"};

    private UsernameGenerator() {}

    public static String generate(Random random, Collection<String> excluded) {
        Set<String> taken = new HashSet<>();
        for (String name : excluded) taken.add(normalize(name));
        String candidate;
        int attempts = 0;
        do {
            String separator = new String[] {"", "", " ", "_"}[random.nextInt(4)];
            String base;
            switch (random.nextInt(5)) {
                case 0: base = pick(NAMES, random) + separator + pick(WORDS, random); break;
                case 1: base = pick(WORDS, random) + separator + pick(WORDS, random); break;
                case 2: base = pick(NAMES, random) + separator + new String[] {"RS", "PvM", "Plays", "Alt", ""}[random.nextInt(5)]; break;
                default: base = pick(START, random) + pick(MIDDLE, random) + pick(END, random);
            }
            String suffix = random.nextInt(3) == 0 || attempts > 24
                    ? Integer.toString(random.nextInt(10000)) : "";
            candidate = base.substring(0, Math.min(base.length(), 12 - suffix.length())).trim() + suffix;
            if (random.nextInt(4) == 0) candidate = candidate.toLowerCase(Locale.ENGLISH);
            attempts++;
        } while (attempts < 64 && taken.contains(normalize(candidate)));
        if (taken.contains(normalize(candidate))) {
            int guest = 0;
            do { candidate = "Guest" + guest++; } while (taken.contains(normalize(candidate)));
        }
        return candidate;
    }

    public static String normalize(String name) {
        return name == null ? "" : name.replace('_', ' ').replace('\u00a0', ' ').trim().toLowerCase(Locale.ENGLISH);
    }

    private static String pick(String[] words, Random random) { return words[random.nextInt(words.length)]; }
}

package com.celebritymode.movement;

import net.runelite.api.*;
import net.runelite.api.coords.*;

import javax.inject.Singleton;

@Singleton
public class CollisionService {
    private WorldView view;

    public void bind(WorldView view) {
        this.view = view;
    }

    public boolean canOccupy(WorldPoint point) {
        if (view == null || point == null || point.getPlane() != view.getPlane()) return false;
        LocalPoint p = LocalPoint.fromWorld(view, point);
        CollisionData[] maps = view.getCollisionMaps();
        if (p == null
                || maps == null
                || maps.length <= point.getPlane()
                || maps[point.getPlane()] == null) return false;
        int[][] flags = maps[point.getPlane()].getFlags();
        int x = p.getSceneX(), y = p.getSceneY();
        return x >= 0
                && x < flags.length
                && y >= 0
                && y < flags[x].length
                && (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0;
    }

    public boolean canStep(WorldPoint from, WorldPoint to) {
        if (!canOccupy(from) || !canOccupy(to) || from.getPlane() != to.getPlane()) return false;
        int dx = to.getX() - from.getX(), dy = to.getY() - from.getY();
        if (Math.abs(dx) > 1 || Math.abs(dy) > 1) return false;
        return new WorldArea(from, 1, 1).canTravelInDirection(view, dx, dy);
    }
}

package com.celebritymode.movement;

import com.celebritymode.fan.*;
import com.celebritymode.util.OrientationUtil;

import net.runelite.api.*;
import net.runelite.api.coords.*;

import java.util.*;

import javax.inject.*;

@Singleton
public final class FanMovementController {
    private final CollisionService collision;
    private final FanAnimations animations;

    @Inject
    public FanMovementController(CollisionService collision, FanAnimations animations) {
        this.collision = collision;
        this.animations = animations;
    }

    public void plan(
            FanEntity fan,
            WorldPoint target,
            MovementTrail trail,
            boolean playerRunning,
            WorldView view,
            int cycle) {
        plan(fan, target, trail, playerRunning, view, cycle, false);
    }

    public void plan(
            FanEntity fan,
            WorldPoint target,
            MovementTrail trail,
            boolean playerRunning,
            WorldView view,
            int cycle,
            boolean stoppedCrowd) {
        fan.target = target;
        if (target == null || fan.position == null) return;
        if (fan.position.equals(target)) {
            fan.movementPath = null;
            fan.stalledTicks = 0;
            if (fan.state != FanState.REACTION) animations.setState(fan, FanState.IDLE);
            return;
        }
        WorldPoint waypoint = target;
        // A distant follower advances along the actual player's route before restoring its offset.
        if (!stoppedCrowd && fan.position.distanceTo(target) > 3 && trail.size() > 1) {
            int closest = -1, distance = Integer.MAX_VALUE;
            for (int i = 0; i < trail.size(); i++) {
                WorldPoint point = trail.getDelayedPoint(i);
                int d = point.distanceTo(fan.position);
                if (d < distance) {
                    distance = d;
                    closest = i;
                }
            }
            if (closest >= 0) {
                WorldPoint near = trail.getDelayedPoint(closest);
                if (closest > 0
                        && !near.equals(target)
                        && near.distanceTo(target) > 1
                        && target.distanceTo(trail.getLatest())
                                < near.distanceTo(trail.getLatest()))
                    waypoint =
                            distance <= 1
                                    ? trail.getDelayedPoint(
                                            Math.max(
                                                    0,
                                                    closest
                                                            - (playerRunning
                                                                            || fan.position
                                                                                            .distanceTo(
                                                                                                    target)
                                                                                    >= 4
                                                                    ? 2
                                                                    : 1)))
                                    : near;
            }
        }
        List<WorldPoint> route = route(fan.position, waypoint);
        if (route.isEmpty()) {
            fan.stalledTicks++;
            fan.movementPath = null;
            if (fan.state != FanState.REACTION) animations.setState(fan, FanState.IDLE);
            return;
        }
        fan.stalledTicks = 0;
        boolean run = !stoppedCrowd && (playerRunning || fan.position.distanceTo(target) >= 4);
        int steps = Math.min(run ? 2 : 1, route.size());
        LocalPoint[] path = new LocalPoint[steps + 1];
        path[0] = fan.renderLocation;
        for (int i = 0; i < steps; i++) {
            path[i + 1] = LocalPoint.fromWorld(view, route.get(i));
            if (path[i + 1] == null) {
                fan.stalledTicks = 21;
                return;
            }
            path[i + 1] = path[i + 1].plus(fan.tileJitterX, fan.tileJitterY);
        }
        if (path[0] == null) {
            fan.stalledTicks = 21;
            return;
        }
        fan.movementPath = path;
        fan.movementStartCycle = cycle;
        WorldPoint end = route.get(steps - 1);
        fan.targetOrientation =
                OrientationUtil.facing(
                        route.get(0).getX() - fan.position.getX(),
                        route.get(0).getY() - fan.position.getY());
        fan.position = end;
        animations.setState(fan, run && steps > 1 ? FanState.RUNNING : FanState.WALKING);
    }

    /**
     * Greedy straight segment first; detours explore at most 96 nearby tiles, never the whole
     * scene.
     */
    public List<WorldPoint> route(WorldPoint start, WorldPoint goal) {
        if (start.equals(goal)) return Collections.emptyList();
        List<WorldPoint> direct = new ArrayList<>(2);
        WorldPoint cursor = start;
        for (int i = 0; i < 2 && !cursor.equals(goal); i++) {
            WorldPoint next =
                    FormationPlanner.offset(
                            cursor,
                            Integer.signum(goal.getX() - cursor.getX()),
                            Integer.signum(goal.getY() - cursor.getY()));
            if (!collision.canStep(cursor, next)) break;
            direct.add(next);
            cursor = next;
        }
        if (!direct.isEmpty()) return direct;
        java.util.Deque<WorldPoint> queue = new ArrayDeque<>();
        Map<WorldPoint, WorldPoint> parent = new HashMap<>();
        queue.add(start);
        parent.put(start, null);
        WorldPoint best = start;
        int explored = 0;
        while (!queue.isEmpty() && explored++ < 96) {
            WorldPoint p = queue.removeFirst();
            if (p.distanceTo(goal) < best.distanceTo(goal)) best = p;
            if (p.equals(goal)) {
                best = p;
                break;
            }
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++) {
                    if (dx == 0 && dy == 0) continue;
                    WorldPoint next = FormationPlanner.offset(p, dx, dy);
                    if (next.distanceTo(start) > 6
                            || parent.containsKey(next)
                            || parent.size() >= 96
                            || !collision.canStep(p, next)) continue;
                    parent.put(next, p);
                    queue.addLast(next);
                }
        }
        if (best.equals(start)) return Collections.emptyList();
        List<WorldPoint> result = new ArrayList<>();
        for (WorldPoint p = best; !p.equals(start); p = parent.get(p)) result.add(p);
        Collections.reverse(result);
        return result;
    }

    public void render(FanEntity fan, WorldView view, int cycle) {
        if (fan.object == null || fan.renderLocation == null) return;
        if (fan.movementPath != null) {
            double progress = Math.max(0, Math.min(1, (cycle - fan.movementStartCycle) / 30.0));
            int count = fan.movementPath.length - 1;
            double scaled = progress * count;
            int segment = Math.min(count - 1, (int) scaled);
            double fraction = scaled - segment;
            LocalPoint a = fan.movementPath[segment], b = fan.movementPath[segment + 1];
            fan.renderLocation =
                    new LocalPoint(
                            (int) Math.round(a.getX() + (b.getX() - a.getX()) * fraction),
                            (int) Math.round(a.getY() + (b.getY() - a.getY()) * fraction),
                            view);
            if (progress >= 1) fan.movementPath = null;
        }
        fan.orientation = OrientationUtil.approach(fan.orientation, fan.targetOrientation);
        fan.object.setOrientation(fan.orientation);
        fan.object.setLocation(fan.renderLocation, view.getPlane());
    }
}

package com.celebritymode.movement;

import com.celebritymode.CelebrityModeConfig;
import com.celebritymode.fan.FanEntity;

import net.runelite.api.coords.WorldPoint;

import java.util.*;

import javax.inject.*;

@Singleton
public class FormationPlanner {
    private final CelebrityModeConfig config;
    private final CollisionService collision;

    @Inject
    public FormationPlanner(CelebrityModeConfig config, CollisionService collision) {
        this.config = config;
        this.collision = collision;
    }

    public void reassignSlots(List<FanEntity> fans) {
        for (int i = 0; i < fans.size(); i++) fans.get(i).formationSlot = i;
    }

    public WorldPoint chooseTarget(
            FanEntity fan,
            WorldPoint player,
            int dx,
            int dy,
            MovementTrail trail,
            Set<WorldPoint> reserved) {
        return chooseTarget(fan, player, dx, dy, trail, reserved, 0);
    }

    public WorldPoint chooseTarget(
            FanEntity fan, WorldPoint player, int dx, int dy, MovementTrail trail,
            Set<WorldPoint> reserved, int stationaryTicks) {
        int spread = Math.max(1, Math.min(8, config.maxSpread()));
        FormationStyle style = config.formationStyle();
        int delay =
                style == FormationStyle.TRAIL
                        ? fan.trailOffset
                        : style == FormationStyle.SWARM
                                ? 1 + fan.trailOffset / 5
                                : style == FormationStyle.LOOSE_CROWD
                                        ? 1 + fan.trailOffset / 2
                                        : 1 + fan.trailOffset / 3;
        WorldPoint anchor = trail.getDelayedPoint(Math.max(0, delay - stationaryTicks / 2));
        if (anchor == null) anchor = player;
        // Each follower has its own persistent angle and depth, independent of list index/rows.
        double angle = fan.id * 2.399963229728653 + 0.71;
        double lateral = Math.sin(angle) * spread * (style == FormationStyle.TRAIL ? 0.55 : 0.95);
        double behind =
                style == FormationStyle.SWARM
                        ? 0.5 + (1 + Math.cos(angle * 1.37)) * 0.6
                        : 0.75 + (1 + Math.cos(angle * 1.37)) * 1.1;
        int hx = Integer.signum(dx), hy = Integer.signum(dy);
        if (hx == 0 && hy == 0) hy = 1;
        WorldPoint preferred =
                offset(
                        anchor,
                        (int) Math.round(-hx * behind - hy * lateral),
                        (int) Math.round(-hy * behind + hx * lateral));
        WorldPoint best =
                valid(preferred, player, reserved) && connected(anchor, preferred)
                        ? preferred
                        : null;
        // Fixed search budget, independent of scene size; prefer unique tiles then sharing.
        for (int radius = 1; best == null && radius <= 4; radius++)
            for (int x = -radius; best == null && x <= radius; x++)
                for (int y = -radius; best == null && y <= radius; y++) {
                    if (Math.max(Math.abs(x), Math.abs(y)) != radius) continue;
                    WorldPoint p = offset(preferred, x, y);
                    int lateralDistance =
                            Math.abs(
                                    -hy * (p.getX() - anchor.getX())
                                            + hx * (p.getY() - anchor.getY()));
                    if (lateralDistance <= spread * (Math.abs(hx) + Math.abs(hy))
                            && valid(p, player, reserved)
                            && connected(anchor, p)) best = p;
                }
        if (best == null && collision.canOccupy(anchor)) best = anchor;
        if (best == null && collision.canOccupy(player)) best = player;
        if (best != null) reserved.add(best);
        return best;
    }

    /** A stable minority gradually breaks away; the majority keeps following in formation. */
    public boolean shouldGather(FanEntity fan, int stationaryTicks) {
        return Math.floorMod(fan.id * 37, 100) < 30
                && stationaryTicks >= 25 + Math.floorMod(fan.id * 19, 80);
    }

    /** Hold a good viewing spot, with rare one-tile adjustments rather than radial wandering. */
    public WorldPoint chooseIdleTarget(
            FanEntity fan, WorldPoint player, Set<WorldPoint> reserved, Random random, int tick) {
        if (fan.state == com.celebritymode.fan.FanState.REACTION) {
            reserved.add(fan.position);
            return fan.position;
        }
        int crowdSize = Math.max(1, Math.min(com.celebritymode.fan.CrowdArrival.MAX_FANS, config.crowdSize()));
        int radius = Math.max(3, (int) Math.ceil(Math.sqrt(crowdSize / Math.PI)));
        if (fan.idleTarget != null && collision.canOccupy(fan.idleTarget)
                && fan.idleTarget.distanceTo(player) <= radius) {
            if (!fan.idleTarget.equals(fan.position) || tick < fan.nextWanderTick) {
                reserved.add(fan.idleTarget);
                return fan.idleTarget;
            }
            fan.nextWanderTick = tick + 100 + random.nextInt(200);
            // Most opportunities pass without moving, even after a long pause.
            if (random.nextInt(5) != 0) {
                reserved.add(fan.idleTarget);
                return fan.idleTarget;
            }
        }
        WorldPoint origin = fan.idleTarget == null ? player : fan.position;
        WorldPoint preferred = fan.position;
        for (int attempt = 0; attempt < 24; attempt++) {
            int reach = fan.idleTarget == null ? radius : 1;
            WorldPoint candidate = offset(origin,
                    random.nextInt(2 * reach + 1) - reach,
                    random.nextInt(2 * reach + 1) - reach);
            if (candidate.distanceTo(player) > radius
                    || candidate.equals(player)
                    || (config.respectPersonalSpace() && candidate.distanceTo(player) < 2)
                    || reserved.contains(candidate)
                    || !collision.canOccupy(candidate)
                    || !connected(origin, candidate)) continue;
            preferred = candidate;
            break;
        }
        fan.idleTarget = preferred;
        fan.nextWanderTick = tick + 100 + random.nextInt(200);
        if (preferred != null) reserved.add(preferred);
        return preferred;
    }

    /**
     * Fans enter on the outskirts and approach on foot, rather than materializing on the player.
     */
    public WorldPoint chooseArrivalPoint(
            FanEntity fan, WorldPoint player, WorldPoint fallback, Set<WorldPoint> reserved) {
        double angle = fan.id * 2.399963229728653;
        for (int attempt = 0; attempt < 24; attempt++) {
            int radius = 4 + (fan.id + attempt) % 3;
            double heading = angle + attempt * 0.45;
            WorldPoint candidate =
                    offset(
                            player,
                            (int) Math.round(Math.cos(heading) * radius),
                            (int) Math.round(Math.sin(heading) * radius));
            if (collision.canOccupy(candidate)
                    && !reserved.contains(candidate)
                    && connected(player, candidate)) {
                reserved.add(candidate);
                return candidate;
            }
        }
        return fallback;
    }

    private boolean valid(WorldPoint p, WorldPoint player, Set<WorldPoint> reserved) {
        return collision.canOccupy(p)
                && (!config.respectPersonalSpace()
                        || (p.distanceTo(player) >= 2 && !reserved.contains(p)));
    }

    private boolean connected(WorldPoint from, WorldPoint to) {
        WorldPoint p = from;
        for (int i = 0; i < 16 && !p.equals(to); i++) {
            WorldPoint next =
                    offset(
                            p,
                            Integer.signum(to.getX() - p.getX()),
                            Integer.signum(to.getY() - p.getY()));
            if (!collision.canStep(p, next)) return false;
            p = next;
        }
        return p.equals(to);
    }

    public static WorldPoint offset(WorldPoint p, int x, int y) {
        return new WorldPoint(p.getX() + x, p.getY() + y, p.getPlane());
    }
}

package com.celebritymode.movement;

public enum FormationStyle {
    ENTOURAGE,
    TRAIL,
    LOOSE_CROWD,
    SWARM
}

package com.celebritymode.movement;

import net.runelite.api.coords.WorldPoint;

import java.util.*;

/**
 * Scene-space world points: never canonical instance-template coordinates. Cleared on scene
 * changes.
 */
public final class MovementTrail {
    private final Deque<WorldPoint> points = new ArrayDeque<>();
    private final int capacity;

    public MovementTrail() {
        this(80);
    }

    public MovementTrail(int capacity) {
        if (capacity < 1) throw new IllegalArgumentException("capacity");
        this.capacity = capacity;
    }

    public void update(WorldPoint point) {
        if (point == null || point.equals(points.peekFirst())) return;
        points.addFirst(point);
        while (points.size() > capacity) points.removeLast();
    }

    public WorldPoint getDelayedPoint(int delay) {
        if (points.isEmpty()) return null;
        int i = 0;
        for (WorldPoint p : points) if (i++ >= Math.max(0, delay)) return p;
        return points.peekLast();
    }

    public WorldPoint getLatest() {
        return points.peekFirst();
    }

    public int size() {
        return points.size();
    }

    public List<WorldPoint> snapshot() {
        return new ArrayList<>(points);
    }

    public void clear() {
        points.clear();
    }
}

package com.celebritymode.overlay;

import com.celebritymode.CelebrityModeConfig;
import com.celebritymode.fan.*;

import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;

import javax.inject.*;

@Singleton
public final class CelebrityModeOverlay extends Overlay {
    private final Client client;
    private final CelebrityModeConfig config;
    private final FanManager manager;

    @Inject
    public CelebrityModeOverlay(Client client, CelebrityModeConfig config, FanManager manager) {
        this.client = client;
        this.config = config;
        this.manager = manager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        WorldView view = manager.getView();
        if (view == null || client.getGameState() != GameState.LOGGED_IN) return null;
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setFont(FontManager.getRunescapeBoldFont());
            FontMetrics metrics = g.getFontMetrics();
            List<Rectangle> placed = new ArrayList<>(30);
            Rectangle viewport =
                    new Rectangle(
                            client.getViewportXOffset(),
                            client.getViewportYOffset(),
                            client.getViewportWidth(),
                            client.getViewportHeight());
            g.clip(viewport);
            if (config.debugMode())
                for (WorldPoint point : manager.getBreadcrumbs())
                    tile(g, view, point, new Color(0, 200, 255, 90));
            for (FanEntity fan : manager.getFans()) {
                LocalPoint location = fan.getRenderLocation();
                if (!fan.isVisible() || location.getWorldView() != view.getId()) continue;
                net.runelite.api.Point p =
                        Perspective.localToCanvas(client, location, view.getPlane(), 210);
                if (p == null || !viewport.contains(p.getX(), p.getY())) continue;
                if (config.debugMode()) {
                    tile(g, view, fan.target, new Color(255, 100, 0, 120));
                    draw(
                            g,
                            metrics,
                            p.getX(),
                            p.getY() + 25,
                            fan.id
                                    + " / "
                                    + fan.formationSlot
                                    + " "
                                    + fan.state
                                    + (fan.target == null
                                            ? ""
                                            : " d=" + fan.position.distanceTo(fan.target)),
                            Color.CYAN);
                }
                int baseline = p.getY();
                if (fan.overheadText != null) {
                    String text = fan.overheadText;
                    Rectangle box =
                            new Rectangle(
                                    p.getX() - metrics.stringWidth(text) / 2,
                                    baseline - metrics.getAscent(),
                                    metrics.stringWidth(text),
                                    metrics.getHeight());
                    // At most one pass per previously placed label, with a restart when pushed
                    // upward.
                    for (int attempts = 0; attempts < placed.size() + 1; attempts++) {
                        boolean moved = false;
                        for (Rectangle other : placed)
                            if (box.intersects(other)) {
                                box.y = other.y - box.height - 2;
                                moved = true;
                                break;
                            }
                        if (!moved) break;
                    }
                    baseline = box.y + metrics.getAscent();
                    if (viewport.intersects(box)) {
                        draw(g, metrics, p.getX(), baseline, text, Color.YELLOW);
                        placed.add(box);
                    }
                }
                if (config.showFanNames())
                    draw(
                            g,
                            metrics,
                            p.getX(),
                            baseline - metrics.getHeight() - 2,
                            fan.displayName,
                            new Color(230, 230, 230));
            }
        } finally {
            g.dispose();
        }
        return null;
    }

    private void tile(Graphics2D g, WorldView view, WorldPoint point, Color color) {
        if (point == null) return;
        LocalPoint local = LocalPoint.fromWorld(view, point);
        if (local == null) return;
        Polygon polygon = Perspective.getCanvasTilePoly(client, local);
        if (polygon != null) {
            g.setColor(color);
            g.fill(polygon);
        }
    }

    private void draw(Graphics2D g, FontMetrics metrics, int x, int y, String text, Color color) {
        int left = x - metrics.stringWidth(text) / 2;
        g.setColor(Color.BLACK);
        g.drawString(text, left + 1, y + 1);
        g.setColor(color);
        g.drawString(text, left, y);
    }
}

