package com.celebritymode.pm;

import static org.junit.Assert.*;
import java.util.*;
import org.junit.Test;

public class FanDialogueGeneratorTest {
    @Test
    public void corpusHasVariedLegalNamesResolvedTokensAndWeightedTones() {
        FanDialogueGenerator generator = new FanDialogueGenerator();
        Random random = new Random(709);
        Set<String> names = new HashSet<>(), lines = new HashSet<>();
        EnumMap<FanMessage.Archetype, Integer> counts = new EnumMap<>(FanMessage.Archetype.class);
        int nostalgic = 0, brief = 0, totalLength = 0;
        for (int i = 0; i < 10000; i++) {
            FanMessage message = generator.generate(random, "Local Hero", i);
            assertTrue(message.getUsername(), message.getUsername().matches("[A-Za-z0-9 _]{1,12}"));
            assertFalse(message.getUsername().replace('_', ' ').equalsIgnoreCase("Local Hero"));
            assertFalse(message.getText().contains("{"));
            if (message.getText().contains("xD") || message.getText().contains("@@@@@")) nostalgic++;
            assertFalse(message.getText().contains("}"));
            assertTrue(message.getText().length() <= 160);
            if (message.getText().length() <= 40) brief++;
            totalLength += message.getText().length();
            assertEquals(i, message.getCreatedNanos());
            counts.merge(message.getArchetype(), 1, Integer::sum);
            names.add(message.getUsername());
            lines.add(message.getText());
        }
        assertTrue("Inbox spam is mostly brief: " + brief, brief > 8000);
        assertTrue("Average inbox length: " + totalLength / 10000.0, totalLength < 10000 * 32);
        assertTrue("Older chat flourishes remain occasional", nostalgic > 0 && nostalgic < 500);
        assertTrue("Distinct handles: " + names.size(), names.size() > 6500);
        assertTrue("Distinct messages: " + lines.size(), lines.size() > 5000);
        assertTrue(counts.get(FanMessage.Archetype.HYPE) > 4200 && counts.get(FanMessage.Archetype.HYPE) < 4800);
        assertTrue(counts.get(FanMessage.Archetype.FRIEND) > 2200 && counts.get(FanMessage.Archetype.FRIEND) < 2800);
        assertTrue(counts.get(FanMessage.Archetype.REQUEST) > 1700 && counts.get(FanMessage.Archetype.REQUEST) < 2300);
        assertTrue(counts.get(FanMessage.Archetype.SKEPTIC) > 700 && counts.get(FanMessage.Archetype.SKEPTIC) < 1300);
    }

    @Test
    public void hostileNameMarkupDoesNotEnterMessages() {
        FanDialogueGenerator generator = new FanDialogueGenerator();
        Random random = new Random(1);
        for (int i = 0; i < 100; i++) {
            String text = generator.generate(random, "<img=1>Hero<col=ff0000>{boss}", i).getText();
            assertFalse(text.contains("<img"));
            assertFalse(text.contains("<col"));
            assertFalse(text.contains("{"));
        }
    }
}

package com.celebritymode.pm;

import static org.junit.Assert.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class FanMessageSchedulerTest {
    @Test
    public void poissonDelaysMatchEveryRateAndIncludeClumpsAndLulls() {
        for (TrafficIntensity intensity : TrafficIntensity.values()) {
            Random random = new Random(83);
            double total = 0;
            long min = Long.MAX_VALUE, max = 0;
            for (int i = 0; i < 100000; i++) {
                long delay = FanMessageScheduler.nextDelayNanos(random, intensity);
                assertTrue(delay > 0);
                total += delay;
                min = Math.min(min, delay);
                max = Math.max(max, delay);
            }
            double mean = total / 100000;
            double expected = (double) TimeUnit.MINUTES.toNanos(1) / intensity.getMessagesPerMinute();
            assertEquals(expected, mean, expected * 0.02);
            assertTrue(min < expected / 20);
            assertTrue(max > expected * 6);
        }
    }

    @Test
    public void producerBufferDispatchAndStaleMessageWorkAreBounded() {
        ManualTimer timer = new ManualTimer();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(3), () -> timer.now, () -> timer);
        scheduler.configure(true, TrafficIntensity.PEAK_WORLD_RECORD, "Hero");
        for (int i = 0; i < 300; i++) timer.runNext();
        assertEquals(32, scheduler.getPendingCount());
        assertEquals(268, scheduler.getDroppedCount());
        // The client missed all these messages, so don't replay the old inbox.
        assertTrue(scheduler.drain().isEmpty());
        assertEquals(0, scheduler.getPendingCount());
        for (int i = 0; i < 20; i++) timer.runNext();
        int sent = 0;
        for (int i = 0; i < 20; i++) {
            List<FanMessage> batch = scheduler.drain();
            assertTrue(batch.size() <= 2);
            sent += batch.size();
        }
        assertEquals(12, sent);
        timer.now += TimeUnit.SECONDS.toNanos(1);
        assertFalse(scheduler.drain().isEmpty());
        scheduler.shutdown();
        assertEquals(0, scheduler.getPendingCount());
        assertTrue(timer.isShutdown());
        assertTrue(scheduler.drain().isEmpty());
    }

    @Test
    public void cancelledOldCallbacksCannotProduceAfterDisableOrRestart() {
        List<ManualTimer> timers = new ArrayList<>();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(2),
                () -> timers.get(timers.size() - 1).now, () -> {
                    ManualTimer timer = new ManualTimer();
                    timers.add(timer);
                    return timer;
                });
        scheduler.configure(true, TrafficIntensity.RELAXED, "Hero");
        Runnable stale = timers.get(0).nextCallback();
        timers.get(0).runNext();
        scheduler.configure(false, TrafficIntensity.RELAXED, "Hero");
        stale.run(); // Simulate a callback that was already entering its synchronized block.
        assertEquals(0, scheduler.getPendingCount());
        scheduler.configure(true, TrafficIntensity.STREAMER, "Hero");
        stale.run();
        assertEquals(0, scheduler.getPendingCount());
        ManualTimer timer = timers.get(1);
        for (int i = 0; i < 40; i++) scheduler.configure(true, TrafficIntensity.STREAMER, "New Name");
        assertEquals("Name refresh doesn't restart worker", 2, timers.size());
        assertEquals("Only one timer is outstanding", 1, timer.tasks.size());
        timer.runNext();
        assertEquals(1, scheduler.getPendingCount());
        scheduler.shutdown();
    }
}

